using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// Data + position of one reveal rectangle. The fog shader reads the resolved
    /// rectangle every frame, so this component only has to describe it.
    /// </summary>
    [ExecuteAlways]
    public sealed class VisionWindow : MonoBehaviour
    {
        [SerializeField] Transform owner;
        [SerializeField] Vector2 offset = new Vector2(8f, 0f);

        public Transform Owner => owner;
        public Vector2 Offset => offset;
        public Vector2 Size => new Vector2(transform.localScale.x, transform.localScale.y);

        void LateUpdate() => Refresh();

        void OnValidate() => Refresh();

        public void Configure(Transform newOwner, Vector2 newOffset)
        {
            owner = newOwner;
            offset = newOffset;
            Refresh();
        }

        public void SetSize(Vector2 size)
        {
            if (size.x <= 0f || size.y <= 0f) return;

            transform.localScale = new Vector3(size.x, size.y, 1f);
        }

        /// <summary>Where the hole should be this frame, independent of transform sync order.</summary>
        public Vector2 ResolveCenter() =>
            owner == null ? (Vector2)transform.position : (Vector2)owner.position + offset;

        public void Refresh()
        {
            Vector2 target = ResolveCenter();
            if (((Vector2)transform.position - target).sqrMagnitude < 0.000001f) return;

            transform.position = new Vector3(target.x, target.y, 0f);
        }

        void OnDrawGizmos()
        {
            Gizmos.color = new Color(1f, 0.92f, 0.55f, 0.6f);
            Gizmos.DrawWireCube(ResolveCenter(), Size);
        }
    }
}

using System.Collections;
using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// Drives the fog material with the rectangles of every vision window.
    /// 通关时还会用同一套"从若干点扩散"的逻辑把整层遮蔽擦掉。
    /// </summary>
    [RequireComponent(typeof(SpriteRenderer))]
    public sealed class VisionFog : MonoBehaviour
    {
        [SerializeField] VisionWindow[] windows = new VisionWindow[2];

        [Header("Window Edge")]
        [SerializeField] bool showWindowEdge = true;
        [SerializeField, Range(0f, 1f)] float windowEdgeStrength = 1f;

        [Header("Clear Dissolve")]
        [Tooltip("通关时遮蔽层被擦掉的时长")]
        [SerializeField] float dissolveDuration = 1.8f;

        [Tooltip("中间隔离墙所在位置，视窗不会越过这条线")]
        [SerializeField] float splitX;

        [SerializeField] float dissolveSoftness = 0.4f;

        [Tooltip("扩散起点，相对遮蔽层中心的偏移")]
        [SerializeField] Vector2[] dissolveSeedOffsets =
        {
            new Vector2(-6f, 3f),
            new Vector2(5f, -3f),
            new Vector2(-2f, -4f),
            new Vector2(4f, 4f)
        };

        static readonly int RectAId = Shader.PropertyToID("_RectA");
        static readonly int RectBId = Shader.PropertyToID("_RectB");
        static readonly int EdgeStrengthId = Shader.PropertyToID("_EdgeStrength");
        static readonly int SeedsId = Shader.PropertyToID("_Seeds");
        static readonly int RadiiId = Shader.PropertyToID("_Radii");
        static readonly int DissolveSoftnessId = Shader.PropertyToID("_DissolveSoftness");
        static readonly Vector4 Disabled = new Vector4(9999f, 9999f, 0.001f, 0.001f);

        const int MaxSeeds = 4;

        readonly Vector4[] seeds = new Vector4[MaxSeeds];
        readonly float[] radii = new float[MaxSeeds];
        readonly float[] seedMaxRadius = new float[MaxSeeds];

        SpriteRenderer fog;
        MaterialPropertyBlock block;

        public bool IsDissolving { get; private set; }

        /// <summary>视窗描边的开关，留给以后的设置面板调用。</summary>
        public bool ShowWindowEdge
        {
            get => showWindowEdge;
            set
            {
                if (showWindowEdge == value) return;

                showWindowEdge = value;
                Push();
            }
        }

        void LateUpdate() => Push();

        void OnValidate() => Push();

        public void Configure(VisionWindow left, VisionWindow right)
        {
            windows = new[] { left, right };
            Push();
        }

        /// <summary>换关时把遮蔽层恢复原状（扩散进度与可见性都清掉）。</summary>
        public void ResetFog()
        {
            EnsureRefs();

            IsDissolving = false;
            for (int i = 0; i < MaxSeeds; i++) radii[i] = 0f;

            if (fog != null)
            {
                fog.enabled = true;
                Push();
            }
        }

        /// <summary>从几个起点向外扩散，把整层遮蔽擦掉。</summary>
        public IEnumerator DissolveRoutine()
        {
            if (IsDissolving) yield break;

            EnsureRefs();
            if (fog == null) yield break;

            IsDissolving = true;
            PrepareDissolveSeeds();

            float timer = 0f;
            while (timer < 1f)
            {
                timer += Time.deltaTime / Mathf.Max(dissolveDuration, 0.01f);
                UpdateDissolveRadii(Mathf.Clamp01(timer));
                yield return null;
            }

            UpdateDissolveRadii(1f);
            Push();
            fog.enabled = false;
        }

        void PrepareDissolveSeeds()
        {
            EnsureRefs();

            Bounds bounds = fog.bounds;
            Vector2 center = fog.transform.position;
            int count = Mathf.Min(dissolveSeedOffsets != null ? dissolveSeedOffsets.Length : 0, MaxSeeds);

            for (int i = 0; i < MaxSeeds; i++)
            {
                radii[i] = 0f;

                if (i >= count)
                {
                    seeds[i] = Vector4.zero;
                    seedMaxRadius[i] = 0f;
                    continue;
                }

                Vector2 p = center + dissolveSeedOffsets[i];
                seeds[i] = new Vector4(p.x, p.y, 0f, 0f);

                float max = 0f;
                Vector3 min = bounds.min, maxCorner = bounds.max;
                for (int c = 0; c < 4; c++)
                {
                    var corner = new Vector2(
                        (c & 1) == 0 ? min.x : maxCorner.x,
                        (c & 2) == 0 ? min.y : maxCorner.y);
                    max = Mathf.Max(max, Vector2.Distance(p, corner));
                }

                seedMaxRadius[i] = max + dissolveSoftness;
            }

            Push();
        }

        void UpdateDissolveRadii(float t)
        {
            for (int i = 0; i < MaxSeeds; i++)
            {
                if (seedMaxRadius[i] <= 0f) { radii[i] = 0f; continue; }

                float start = i * 0.08f;
                float local = Mathf.Clamp01((t - start) / Mathf.Max(0.01f, 1f - start));
                radii[i] = Mathf.Lerp(0f, seedMaxRadius[i], local);
            }
        }

        public void Push()
        {
            EnsureRefs();
            if (fog == null || block == null) return;

            fog.GetPropertyBlock(block);
            block.SetVector(RectAId, Pack(0));
            block.SetVector(RectBId, Pack(1));
            block.SetFloat(EdgeStrengthId, showWindowEdge ? Mathf.Clamp01(windowEdgeStrength) : 0f);
            block.SetVectorArray(SeedsId, seeds);
            block.SetFloatArray(RadiiId, radii);
            block.SetFloat(DissolveSoftnessId, dissolveSoftness);
            fog.SetPropertyBlock(block);
        }

        Vector4 Pack(int index)
        {
            if (windows == null || index >= windows.Length || windows[index] == null) return Disabled;

            var window = windows[index];
            Vector2 center = window.ResolveCenter();
            Vector2 half = window.Size * 0.5f;

            // 视窗不能越过中间的隔离墙：右侧窗口裁掉中线左边，左侧窗口裁掉右边，
            // 否则视窗贴到边界时会漏出对侧一小条地形。
            float minX = center.x - half.x;
            float maxX = center.x + half.x;

            if (center.x >= splitX) minX = Mathf.Max(minX, splitX);
            else maxX = Mathf.Min(maxX, splitX);

            float width = maxX - minX;
            if (width <= 0.001f) return Disabled;

            center.x = (minX + maxX) * 0.5f;
            half.x = width * 0.5f;

            return new Vector4(center.x, center.y, Mathf.Max(half.x, 0.001f), Mathf.Max(half.y, 0.001f));
        }

        void EnsureRefs()
        {
            if (fog == null) fog = GetComponent<SpriteRenderer>();
            if (block == null) block = new MaterialPropertyBlock();
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 污渍的溶解动画：从若干个起点向外扩散，把贴图逐渐擦掉。
    /// 每个起点有各自的半径和起始延时，扩散完不等大，看起来才像手擦的。
    /// </summary>
    [RequireComponent(typeof(SpriteRenderer))]
    public sealed class StainDissolve : MonoBehaviour
    {
        [SerializeField] SpriteRenderer target;

        [Tooltip("扩散起点，相对污渍中心的偏移（世界单位）")]
        [SerializeField] Vector2[] seedOffsets =
        {
            new Vector2(-0.22f, 0.06f),
            new Vector2(0.18f, 0.22f),
            new Vector2(0.12f, -0.22f)
        };

        [SerializeField] float duration = 0.7f;
        [SerializeField] float softness = 0.22f;

        [Tooltip("相邻起点之间的起始延时（占整段的比例）")]
        [SerializeField] float stagger = 0.12f;

        static readonly int SeedsId = Shader.PropertyToID("_Seeds");
        static readonly int RadiiId = Shader.PropertyToID("_Radii");
        static readonly int SoftnessId = Shader.PropertyToID("_Softness");

        const int MaxSeeds = 4;

        readonly Vector4[] seeds = new Vector4[MaxSeeds];
        readonly float[] radii = new float[MaxSeeds];
        readonly float[] seedMaxRadius = new float[MaxSeeds];

        MaterialPropertyBlock block;
        float timer = -1f;

        public bool Playing => timer >= 0f;
        public bool Finished { get; private set; }

        public void Play()
        {
            if (Playing || Finished) return;
            if (target == null) target = GetComponent<SpriteRenderer>();

            PrepareSeeds();
            timer = 0f;
        }

        void PrepareSeeds()
        {
            if (block == null) block = new MaterialPropertyBlock();

            Bounds bounds = target.bounds;
            Vector2 center = target.transform.position;
            int count = Mathf.Min(seedOffsets != null ? seedOffsets.Length : 0, MaxSeeds);

            for (int i = 0; i < MaxSeeds; i++)
            {
                if (i < count)
                {
                    Vector2 p = center + seedOffsets[i];
                    seeds[i] = new Vector4(p.x, p.y, 0f, 0f);

                    // 该起点要扩散到污渍最远角，才算擦干净
                    float max = 0f;
                    Vector3 min = bounds.min, maxCorner = bounds.max;
                    for (int c = 0; c < 4; c++)
                    {
                        var corner = new Vector2(
                            (c & 1) == 0 ? min.x : maxCorner.x,
                            (c & 2) == 0 ? min.y : maxCorner.y);
                        max = Mathf.Max(max, Vector2.Distance(p, corner));
                    }

                    seedMaxRadius[i] = max + softness;
                }
                else
                {
                    seeds[i] = Vector4.zero;
                    seedMaxRadius[i] = 0f;
                }

                radii[i] = 0f;
            }

            target.GetPropertyBlock(block);
            block.SetVectorArray(SeedsId, seeds);
            block.SetFloatArray(RadiiId, radii);
            block.SetFloat(SoftnessId, softness);
            target.SetPropertyBlock(block);
        }

        void Update()
        {
            if (!Playing || Finished) return;

            timer += Time.deltaTime;
            float t = Mathf.Clamp01(timer / Mathf.Max(duration, 0.01f));

            for (int i = 0; i < MaxSeeds; i++)
            {
                if (seedMaxRadius[i] <= 0f) { radii[i] = 0f; continue; }

                float start = i * stagger;
                float local = Mathf.Clamp01((t - start) / Mathf.Max(0.01f, 1f - start));
                radii[i] = Mathf.Lerp(0f, seedMaxRadius[i], local);
            }

            block.SetFloatArray(RadiiId, radii);
            target.SetPropertyBlock(block);

            if (t < 1f) return;

            Finished = true;
            target.enabled = false;
        }
    }
}

Shader "GrayBox/VisionFog"
{
    Properties
    {
        _MainTex ("Fog Texture", 2D) = "white" {}
        _Color ("Tint", Color) = (1, 1, 1, 1)
        _Feather ("Feather (world units)", Range(0.01, 3)) = 0.4
        _Tile ("Texture Tiling", Vector) = (1, 1, 0, 0)

        [Header(Window Edge)]
        _EdgeColor ("Edge Color", Color) = (0.33, 0.26, 0.21, 1)
        _EdgeWidth ("Edge Width (world units)", Range(0, 0.5)) = 0.08

        _RectA ("Rect A (center.xy, halfSize.xy)", Vector) = (9999, 9999, 0.001, 0.001)
        _RectB ("Rect B (center.xy, halfSize.xy)", Vector) = (9999, 9999, 0.001, 0.001)
    }

    SubShader
    {
        Tags
        {
            "Queue" = "Transparent"
            "RenderType" = "Transparent"
            "IgnoreProjector" = "True"
            "PreviewType" = "Plane"
        }

        Blend SrcAlpha OneMinusSrcAlpha
        ZWrite Off
        Cull Off

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float4 color  : COLOR;
                float2 uv     : TEXCOORD0;
            };

            struct v2f
            {
                float4 pos      : SV_POSITION;
                float3 worldPos : TEXCOORD0;
                float4 color    : COLOR;
                float2 uv       : TEXCOORD1;
            };

            sampler2D _MainTex;
            fixed4 _Color;
            float  _Feather;
            float4 _Tile;
            fixed4 _EdgeColor;
            float  _EdgeWidth;

            // 由 VisionFog 每帧推送：0 = 关闭描边，1 = 完全开启
            float _EdgeStrength;

            // 通关时的溶解：与污渍使用同一套扩散逻辑
            float4 _Seeds[4];
            float _Radii[4];
            float _DissolveSoftness;

            float4 _RectA;
            float4 _RectB;

            v2f vert(appdata v)
            {
                v2f o;
                o.pos = UnityObjectToClipPos(v.vertex);
                o.worldPos = mul(unity_ObjectToWorld, v.vertex).xyz;
                o.color = v.color;
                o.uv = v.uv;
                return o;
            }

            // 0 inside the rectangle, grows outwards; used to fade the fog back in
            float BoxDistance(float2 p, float4 rect)
            {
                float2 d = abs(p - rect.xy) - rect.zw;
                return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
            }

            fixed4 frag(v2f i) : SV_Target
            {
                // 两块视窗共享一次平滑过渡，重叠区域取最清晰的那个
                float d = min(BoxDistance(i.worldPos.xy, _RectA),
                              BoxDistance(i.worldPos.xy, _RectB));

                float fogAlpha = smoothstep(0.0, max(_Feather, 0.001), d);

                fixed4 tex = tex2D(_MainTex, i.uv * _Tile.xy);
                fixed4 tint = _Color * i.color;

                float3 color = tex.rgb * tint.rgb;
                float alpha = tex.a * tint.a * fogAlpha;

                // 贴着洞口外侧的一条软边，用来在画布与背景同色时标出视窗范围。
                // d 在矩形内部是负数，必须用 step 掐掉，否则整块视窗都会被涂成描边色。
                float stroke = step(0.0, d) *
                               (1.0 - smoothstep(0.0, max(_EdgeWidth, 0.001), d)) *
                               saturate(_EdgeStrength);

                color = lerp(color, _EdgeColor.rgb, stroke);
                alpha = max(alpha, stroke);

                // 多个起点各自向外扩散，取并集把遮蔽层擦掉
                float erase = 0.0;
                [unroll]
                for (int s = 0; s < 4; s++)
                {
                    float radius = _Radii[s];
                    if (radius <= 0.0) continue;

                    float dist = length(i.worldPos.xy - _Seeds[s].xy);
                    float inside = 1.0 - smoothstep(max(radius - _DissolveSoftness, 0.0), radius, dist);
                    erase = max(erase, inside);
                }

                return fixed4(color, alpha * (1.0 - erase));
            }
            ENDCG
        }
    }

    Fallback Off
}

