                    float inside = 1.0 - smoothstep(max(radius - _Softness, 0.0), radius, dist);
                    erase = max(erase, inside);
                }

                return fixed4(color, alpha * (1.0 - erase));
            }
            ENDCG
        }
    }

    Fallback Off
}

