using System.Text;
using UnityEngine;
using UnityEditor;

var path = "Assets/Prefabs/GrayBox/L004.prefab";
var go = AssetDatabase.LoadAssetAtPath<GameObject>(path);
if (go == null) return "NOT_FOUND";
var sb = new StringBuilder();
void Walk(Transform t, int depth)
{
    var indent = new string(' ', depth * 2);
    var sr = t.GetComponent<SpriteRenderer>();
    var bc = t.GetComponent<BoxCollider2D>();
    sb.AppendLine($"{indent}{t.name}  pos={t.localPosition} scale={t.localScale}"
        + (sr != null ? $"  sort={sr.sortingOrder} draw={sr.drawMode} size={sr.size} sprite={(sr.sprite != null ? sr.sprite.name : "null")}" : "")
        + (bc != null ? $"  boxSize={bc.size} offset={bc.offset} trigger={bc.isTrigger}" : "")
        + (t.GetComponent<Hazard>() != null ? "  [Hazard]" : "")
        + (t.GetComponent<LevelGoal>() != null ? "  [Goal]" : "")
        + (t.GetComponent<Checkpoint>() != null ? "  [Checkpoint]" : ""));
    for (int i = 0; i < t.childCount; i++) Walk(t.GetChild(i), depth + 1);
}
Walk(go.transform, 0);
return sb.ToString();

