    /// <summary>
    /// 压纸钉：一枚插在画纸上的图钉。踩下去会把当前视窗钉在原地，
    /// 人可以走开，那块画布仍然亮着；代价是自己脚下彻底看不见。
    /// 再次踩下、或走远到 releaseDistance 之外即解除。
    /// </summary>
    [RequireComponent(typeof(Collider2D))]
    public sealed class PinStation : MonoBehaviour
    {
        [SerializeField] PlayerSide side = PlayerSide.Left;

        [Tooltip("离开钉子多远后自动解除（世界单位）")]
        [SerializeField] float releaseDistance = 3.5f;

        [Tooltip("踩下后至少保持这么久才允许按距离解除，避免刚踩上就弹开")]
        [SerializeField] float minHoldSeconds = 0.5f;

        [SerializeField] SpriteRenderer visual;
        [SerializeField] Color idleColor = Color.white;
        [SerializeField] Color pinnedColor = new Color(1f, 0.86f, 0.45f, 1f);

        VisionWindow window;
        PlayerMotor2D rider;
        float pinnedAt;

        public MechanismKind Kind => MechanismKind.PinStation;
        public PlayerSide Side => side;
        public bool Pinned => window != null && window.IsAnchored;

        void Reset()
        {
            var col = GetComponent<Collider2D>();
            if (col != null) col.isTrigger = true;
        }

        void Awake()
        {
            if (visual == null) visual = GetComponentInChildren<SpriteRenderer>();
        }

        void OnTriggerEnter2D(Collider2D other)
        {
            var motor = other.GetComponent<PlayerMotor2D>();
            if (motor == null || motor.Side != side) return;

            EnsureWindow();
            if (window == null) return;

            if (window.IsAnchored) Release();
            else Pin(motor);
        }

        void Update()
        {
            if (window == null || !window.IsAnchored || rider == null) return;

            if (Time.time - pinnedAt < minHoldSeconds) return;
            if (Vector2.Distance(rider.transform.position, transform.position) <= releaseDistance) return;

            Release();
        }

        void Pin(PlayerMotor2D motor)
        {
            window.Anchor();
            rider = motor;
            pinnedAt = Time.time;
            ApplyVisual(true);
        }

        void Release()
        {
            if (window != null) window.ReleaseAnchor();

            rider = null;
            ApplyVisual(false);
        }

        void EnsureWindow()
        {
            if (window != null) return;

            foreach (var candidate in FindObjectsOfType<VisionWindow>())
            {
                if (candidate.Side != side) continue;

                window = candidate;
                return;
            }
        }

        void ApplyVisual(bool pinned)
        {
            if (visual == null) return;

            visual.color = pinned ? pinnedColor : idleColor;
        }

        /// <summary>换关、复活时由 LevelSession 统一清掉，避免钉在一个已经卸载的视窗上。</summary>
        public void ForceRelease() => Release();

        public void Configure(PlayerSide newSide) => side = newSide;
    }
}

