namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 未干的颜料块：这一笔刚上色还没干透。站上去一会儿就塌成一摊半透明的水痕，
    /// 过几秒才重新凝住。塌陷期间碰撞体失效——所以它既是路也是陷阱。
    /// </summary>
    [RequireComponent(typeof(Collider2D))]
    public sealed class CrumblePlatform : MonoBehaviour
    {
        enum State { Idle, Collapsing, Gone, Restoring }

        [Header("Timing")]
        [Tooltip("站上去多久开始塌")]
        [SerializeField] float standDelay = 0.6f;

        [Tooltip("塌下去的过程时长")]
        [SerializeField] float collapseDuration = 0.22f;

        [Tooltip("完全消失后多久开始恢复")]
        [SerializeField] float goneDuration = 2.2f;

        [Tooltip("重新凝住的过程时长")]
        [SerializeField] float restoreDuration = 0.35f;

        [Header("Visual")]
        [SerializeField] Transform block;
        [SerializeField] SpriteRenderer blockRenderer;
        [SerializeField] SpriteRenderer puddleRenderer;

        [Tooltip("塌陷后水痕的不透明度")]
        [SerializeField, Range(0f, 1f)] float puddleAlpha = 0.34f;

        [Tooltip("塌陷时压扁到原高度的比例")]
        [SerializeField, Range(0.05f, 1f)] float squash = 0.26f;

        [Header("Revive Guard")]
        [Tooltip("恢复前检查这块位置上方有没有人，有则推迟，避免把人顶起来")]
        [SerializeField] Vector2 riderCheckSize = new Vector2(1.4f, 0.8f);

        [SerializeField] LayerMask playerMask = ~0;

        State state = State.Idle;
        Collider2D body;
        Vector3 blockBasePosition;
        Vector3 blockBaseScale;
        float timer;
        float retryAt;

        public MechanismKind Kind => MechanismKind.CrumblePlatform;
        public bool IsDown => state == State.Collapsing || state == State.Gone;

        void Awake()
        {
            body = GetComponent<Collider2D>();
            if (block != null)
            {
                blockBasePosition = block.localPosition;
                blockBaseScale = block.localScale;
            }

            ApplyProgress(1f);
        }

        void Reset()
        {
            var col = GetComponent<Collider2D>();
            if (col != null) col.isTrigger = false;
        }

        void OnCollisionStay2D(Collision2D collision)
        {
            if (state != State.Idle) return;

            var motor = collision.collider.GetComponent<PlayerMotor2D>();
            if (motor == null) return;

            // 只有踩在顶面才算数，贴着侧面不算
            if (collision.collider.bounds.min.y < transform.position.y - 0.05f) return;

            timer += Time.deltaTime;

            // 塌之前先抖一抖，给玩家一个提前量
            if (block != null && timer > 0.05f)
            {
                float shake = Mathf.Sin(timer * 55f) * 0.025f;
                block.localPosition = blockBasePosition + new Vector3(shake, 0f, 0f);
            }

            if (timer < standDelay) return;

            EnterCollapsing();
        }

        void OnCollisionExit2D(Collision2D collision)
        {
            if (state != State.Idle) return;

            timer = 0f;
            if (block != null) block.localPosition = blockBasePosition;
        }

        void Update()
        {
            if (state == State.Idle) return;

            if (state == State.Collapsing)
            {
                timer += Time.deltaTime;
                float t = Mathf.Clamp01(timer / Mathf.Max(collapseDuration, 0.01f));
                ApplyProgress(1f - t);

                if (t < 1f) return;

                state = State.Gone;
                timer = 0f;
                return;
            }

            if (state == State.Gone)
            {
                timer += Time.deltaTime;
                if (timer < goneDuration) return;
                if (Time.time < retryAt) return;
                if (BlockedByRider())
                {
                    retryAt = Time.time + 0.35f;
                    return;
                }

                state = State.Restoring;
                timer = 0f;
                return;
            }

            if (state == State.Restoring)
            {
                timer += Time.deltaTime;
                float t = Mathf.Clamp01(timer / Mathf.Max(restoreDuration, 0.01f));
                ApplyProgress(t);

                if (t < 1f) return;

                state = State.Idle;
                timer = 0f;
                if (block != null) block.localPosition = blockBasePosition;
            }
        }

        void EnterCollapsing()
        {
            state = State.Collapsing;
            timer = 0f;

            if (body != null) body.enabled = false;
            if (block != null) block.localPosition = blockBasePosition;
        }

        /// <summary>progress 1 = 完整立在原地，0 = 完全塌成一摊水痕。</summary>
        void ApplyProgress(float progress)
        {
            float p = Mathf.Clamp01(progress);

            if (block != null)
            {
                block.localScale = new Vector3(
                    blockBaseScale.x * Mathf.Lerp(1.12f, 1f, p),
                    blockBaseScale.y * Mathf.Lerp(squash, 1f, p),
                    blockBaseScale.z);
            }

            if (blockRenderer != null)
            {
                var c = blockRenderer.color;
                c.a = p;
                blockRenderer.color = c;
                blockRenderer.enabled = p > 0.01f;
            }

            if (puddleRenderer != null)
            {
                var c = puddleRenderer.color;
                c.a = puddleAlpha * (1f - p);
                puddleRenderer.color = c;
                puddleRenderer.enabled = c.a > 0.01f;
            }
        }

        bool BlockedByRider()
        {
            Vector2 center = (Vector2)transform.position + Vector2.up * 0.1f;
            return Physics2D.OverlapBox(center, riderCheckSize, 0f, playerMask) != null;
        }

        public void Configure(Transform newBlock, SpriteRenderer newBlockRenderer, SpriteRenderer newPuddle)
        {
            block = newBlock;
            blockRenderer = newBlockRenderer;
            puddleRenderer = newPuddle;

            if (block != null)
            {
                blockBasePosition = block.localPosition;
                blockBaseScale = block.localScale;
            }
        }
    }
}

