using System.IO;
using System.Text;
using UnityEngine;

var paths = new[]{
    "Assets/Pictures/01_颜料碴_尖刺.png",
    "Assets/Pictures/02_补笔带_显隐.png",
    "Assets/Pictures/03_颜料罐_开关.png",
    "Assets/Pictures/04_留白_存档点.png",
    "Assets/Pictures/07_漏光缝.png",
    "Assets/Pictures/08_压纸钉.png",
    "Assets/Pictures/09_未干颜料块.png",
    "Assets/Pictures/10_游动颜料团.png"};

var sb = new StringBuilder();
foreach (var p in paths)
{
    var bytes = File.ReadAllBytes(p);
    var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    if (!tex.LoadImage(bytes)) { sb.AppendLine(p + " DECODE_FAIL"); continue; }

    int w = tex.width, h = tex.height;
    var px = tex.GetPixels32();
    int minA = 255, transparent = 0, nearWhite = 0;
    int minX = w, maxX = -1, minY = h, maxY = -1;
    for (int y = 0; y < h; y++)
    for (int x = 0; x < w; x++)
    {
        var c = px[y * w + x];
        if (c.a < minA) minA = c.a;
        if (c.a < 16) { transparent++; continue; }
        bool white = c.r > 246 && c.g > 246 && c.b > 246;
        if (white) { nearWhite++; continue; }
        if (x < minX) minX = x; if (x > maxX) maxX = x;
        if (y < minY) minY = y; if (y > maxY) maxY = y;
    }
    Object.DestroyImmediate(tex);

    string bbox = maxX < 0 ? "none" : $"x{minX}..{maxX} y{minY}..{maxY} ({maxX-minX+1}x{maxY-minY+1})";
    sb.AppendLine($"{Path.GetFileName(p)}  {w}x{h}  minAlpha={minA} transparent={transparent * 100f / (w * h):F1}%  nearWhite={nearWhite * 100f / (w * h):F1}%  content={bbox}");
}
return sb.ToString();

