using System.Text;
using UnityEditor;
using UnityEngine;

var map = new (string path, float ppu)[]
{
    ("Assets/Pictures/07_漏光缝.png", 62.5f),
    ("Assets/Pictures/08_压纸钉.png", 200f),
    ("Assets/Pictures/09_未干颜料块.png", 300f),
    ("Assets/Pictures/10_游动颜料团.png", 180f)
};

var sb = new StringBuilder();
foreach (var (path, ppu) in map)
{
    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
    if (importer == null) { sb.AppendLine(path + " NO_IMPORTER"); continue; }

    importer.textureType = TextureImporterType.Sprite;
    importer.spriteImportMode = SpriteImportMode.Single;
    importer.spritePixelsPerUnit = ppu;
    importer.filterMode = FilterMode.Bilinear;
    importer.mipmapEnabled = false;
    importer.alphaIsTransparency = true;
    importer.wrapMode = TextureWrapMode.Clamp;

    var settings = new TextureImporterSettings();
    importer.ReadTextureSettings(settings);
    settings.spriteAlignment = (int)SpriteAlignment.Center;
    settings.spriteMeshType = (int)SpriteMeshType.FullRect;
    importer.SetTextureSettings(settings);
    importer.SaveAndReimport();

    var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(path);
    sb.AppendLine($"{path}  ppu={ppu}  sprite={(sprite != null ? sprite.name : "NULL")}  world={(sprite != null ? sprite.bounds.size.ToString() : "-")}");
}
return sb.ToString();

using System.Text;
using UnityEditor;
using UnityEngine;

var sb = new StringBuilder();
foreach (var p in new[]{
    "Assets/Prefabs/GrayBox/Mechanisms/Goal_Left.prefab",
    "Assets/Prefabs/GrayBox/Mechanisms/Checkpoint.prefab",
    "Assets/Prefabs/GrayBox/Mechanisms/Spike.prefab",
    "Assets/Prefabs/GrayBox/Mechanisms/Switch.prefab",
    "Assets/Prefabs/GrayBox/Mechanisms/ToggleBlock.prefab"})
{
    var go = AssetDatabase.LoadAssetAtPath<GameObject>(p);
    sb.AppendLine("=== " + p + (go == null ? " NULL" : ""));
    if (go == null) continue;

    void Walk(Transform t, int d)
    {
        var ind = new string(' ', d * 2);
        var sr = t.GetComponent<SpriteRenderer>();
        var bc = t.GetComponent<BoxCollider2D>();
        var comps = string.Join(",", System.Array.ConvertAll(t.GetComponents<Component>(), c => c.GetType().Name));
        sb.AppendLine($"{ind}{t.name} pos={t.localPosition} scale={t.localScale} comps=[{comps}]"
            + (sr != null ? $" sort={sr.sortingOrder} draw={sr.drawMode} size={sr.size} pivotSprite={(sr.sprite != null ? sr.sprite.name : "null")}" : "")
            + (bc != null ? $" box={bc.size} off={bc.offset} trig={bc.isTrigger}" : ""));
        for (int i = 0; i < t.childCount; i++) Walk(t.GetChild(i), d + 1);
    }
    Walk(go.transform, 0);
}
return sb.ToString();

