using System.Collections.Generic;
using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

var platPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Platform.prefab");
var goalLeftPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Goal_Left.prefab");
var goalRightPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Goal_Right.prefab");
var lightPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/LightPillar.prefab");
var pinPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/PinStation.prefab");
var crumblePrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/CrumblePlatform.prefab");
var movingPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/MovingPlatform.prefab");

if (platPrefab == null || goalLeftPrefab == null || goalRightPrefab == null
    || lightPrefab == null || pinPrefab == null || crumblePrefab == null || movingPrefab == null)
    return "MISSING_PREFAB";

var report = new StringBuilder();

Transform Group(string name, Transform parent)
{
    var go = new GameObject(name);
    go.transform.SetParent(parent, false);
    return go.transform;
}

GameObject InstantiateTo(GameObject prefab, Scene scene, Transform parent, string name, Vector2 position)
{
    var go = (GameObject)PrefabUtility.InstantiatePrefab(prefab, scene);
    go.name = name;
    go.transform.SetParent(parent, false);
    go.transform.localPosition = new Vector3(position.x, position.y, 0f);
    return go;
}

void AddPlatform(Scene scene, Transform terrain, string name, Vector2 center, Vector2 size)
{
    var go = InstantiateTo(platPrefab, scene, terrain, name, center);
    var sr = go.GetComponent<SpriteRenderer>();
    sr.drawMode = SpriteDrawMode.Tiled;
    sr.tileMode = SpriteTileMode.Continuous;
    sr.size = size;
    var bc = go.GetComponent<BoxCollider2D>();
    bc.size = size;
}

void AddMarker(Transform root, string name, Vector2 position)
{
    var go = new GameObject(name);
    go.transform.SetParent(root, false);
    go.transform.localPosition = new Vector3(position.x, position.y, 0f);
}

GameObject Build(string name, System.Action<Scene, Transform, Transform, Transform, Transform> body)
{
    var scene = EditorSceneManager.NewPreviewScene();
    var root = new GameObject(name);
    EditorSceneManager.MoveGameObjectToScene(root, scene);

    var terrain = Group("Terrain", root.transform);
    var goals = Group("Goals", root.transform);
    var mechs = Group("Mechanisms", root.transform);

    body(scene, root.transform, terrain, goals, mechs);

    var path = "Assets/Prefabs/GrayBox/" + name + ".prefab";
    PrefabUtility.SaveAsPrefabAsset(root, path);
    EditorSceneManager.ClosePreviewScene(scene);

    report.AppendLine(path);
