args.script:
using System.Collections.Generic;
using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEngine;

var report = new StringBuilder();

var defs = new (string id, string display, string prefabPath)[]
{
    ("L006", "关卡 6", "Assets/Prefabs/GrayBox/L006.prefab"),
    ("L007", "关卡 7", "Assets/Prefabs/GrayBox/L007.prefab"),
    ("L008", "关卡 8", "Assets/Prefabs/GrayBox/L008.prefab"),
    ("L009", "关卡 9", "Assets/Prefabs/GrayBox/L009.prefab")
};

var created = new List<LevelConfig>();

foreach (var (id, display, prefabPath) in defs)
{
    var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
    if (prefab == null) { report.AppendLine(prefabPath + " MISSING"); continue; }

    var assetPath = "Assets/GameData/Levels/" + id + ".asset";
    var existing = AssetDatabase.LoadAssetAtPath<LevelConfig>(assetPath);
    var config = existing != null ? existing : ScriptableObject.CreateInstance<LevelConfig>();

    var so = new SerializedObject(config);
    so.FindProperty("levelId").stringValue = id;
    so.FindProperty("displayName").stringValue = display;
    so.FindProperty("enabled").boolValue = true;
    so.FindProperty("levelPrefab").objectReferenceValue = prefab;
    so.FindProperty("windowSize").vector2Value = new Vector2(4f, 3f);
    so.FindProperty("leftWindowOffset").vector2Value = new Vector2(8f, 0f);
    so.FindProperty("rightWindowOffset").vector2Value = new Vector2(-8f, 0f);
    so.ApplyModifiedPropertiesWithoutUndo();

    if (existing == null)
    {
        AssetDatabase.CreateAsset(config, assetPath);
        report.AppendLine("created " + assetPath);
    }
    else
    {
        EditorUtility.SetDirty(existing);
        report.AppendLine("updated " + assetPath);
    }

    created.Add(config);
}

var catalog = AssetDatabase.LoadAssetAtPath<LevelCatalog>("Assets/GameData/LevelCatalog.asset");
if (catalog == null) report.AppendLine("CATALOG_MISSING");
else
{
    var list = new List<LevelConfig>(catalog.Levels);
    foreach (var c in created)
        if (!list.Contains(c)) list.Add(c);

    catalog.SetLevels(list);
    EditorUtility.SetDirty(catalog);

    var names = new StringBuilder();
    foreach (var c in list) names.Append(c != null ? c.LevelId : "<null>").Append(' ');
    report.AppendLine($"catalog now: {names}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return report.ToString();

