var shaderPath = "Assets/Shaders/AdditiveSprite.shader";
var code = @"Shader ""GrayBox/AdditiveSprite""
{
    Properties
    {
        _MainTex (""Texture"", 2D) = ""white"" {}
        _Color (""Tint"", Color) = (1, 1, 1, 1)
    }

    SubShader
    {
        Tags
        {
            ""Queue"" = ""Transparent""
            ""RenderType"" = ""Transparent""
            ""IgnoreProjector"" = ""True""
            ""PreviewType"" = ""Plane""
        }

        // 加色混合：光叠在画面上只会变亮，不会盖住下面的地形
        Blend SrcAlpha One
        ZWrite Off
        Cull Off

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include ""UnityCG.cginc""

            struct appdata
            {
                float4 vertex : POSITION;
                float4 color  : COLOR;
                float2 uv     : TEXCOORD0;
            };

            struct v2f
            {
                float4 pos   : SV_POSITION;
                float4 color : COLOR;
                float2 uv    : TEXCOORD0;
            };

            sampler2D _MainTex;
            fixed4 _Color;

            v2f vert(appdata v)
            {
                v2f o;
                o.pos = UnityObjectToClipPos(v.vertex);
                o.color = v.color * _Color;
                o.uv = v.uv;
                return o;
            }

            fixed4 frag(v2f i) : SV_Target
            {
                fixed4 tex = tex2D(_MainTex, i.uv);
                return fixed4(tex.rgb * i.color.rgb, tex.a * i.color.a);
            }
            ENDCG
        }
    }

    Fallback Off
}
";
