using ThreeCup.GrayBox;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
if (session == null) return "NO_SESSION";

var so = new SerializedObject(session);
var leftW = so.FindProperty("leftWindow").objectReferenceValue as VisionWindow;
var rightW = so.FindProperty("rightWindow").objectReferenceValue as VisionWindow;
if (leftW == null || rightW == null) return "WINDOW_REF_MISSING";

void SetSide(VisionWindow w, PlayerSide side)
{
    var wso = new SerializedObject(w);
    wso.FindProperty("side").enumValueIndex = (int)side;
    wso.ApplyModifiedPropertiesWithoutUndo();
}

SetSide(leftW, PlayerSide.Left);
SetSide(rightW, PlayerSide.Right);

EditorUtility.SetDirty(leftW);
EditorUtility.SetDirty(rightW);
EditorSceneManager.MarkSceneDirty(leftW.gameObject.scene);
var saved = EditorSceneManager.SaveScene(leftW.gameObject.scene);

return $"left={leftW.Side}@{leftW.transform.position} right={rightW.Side}@{rightW.transform.position} saved={saved}";

