using System.Collections;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    if (session == null) { Debug.Log("NO_SESSION"); yield break; }

    yield return null;

    PlayerMotor2D FindPlayer(PlayerSide side)
    {
        foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
            if (p.Side == side) return p;
        return null;
    }

    // ---------- L006 漏光缝 ----------
    session.LoadIndex(5);
    yield return null;
    yield return null;

    var pillars = UnityEngine.Object.FindObjectsOfType<LightPillar>();
    sb.AppendLine($"L006 loaded={session.Current?.LevelId} pillars={pillars.Length}");
    if (pillars.Length > 0) sb.AppendLine($"  pillar at {pillars[0].transform.position} half={pillars[0].HalfSize}");

    var fog = UnityEngine.Object.FindObjectOfType<VisionFog>();
    var fogSr = fog.GetComponent<SpriteRenderer>();
    var mpb = new MaterialPropertyBlock();
    fogSr.GetPropertyBlock(mpb);
    var holes = new Vector4[4];
    mpb.GetVectorArray("_Holes", holes);
    for (int i = 0; i < 4; i++) sb.AppendLine($"  hole[{i}]={holes[i]}");

    // ---------- L007 压纸钉 ----------
    session.LoadIndex(6);
    yield return null;
    yield return null;

    var pin = UnityEngine.Object.FindObjectOfType<PinStation>();
    var left = FindPlayer(PlayerSide.Left);
    sb.AppendLine($"L007 loaded={session.Current?.LevelId} pin={(pin != null)} pinned={pin?.Pinned}");
    if (pin != null && left != null)
    {
        var rb = left.GetComponent<Rigidbody2D>();
        rb.position = pin.transform.position;
        left.transform.position = pin.transform.position;
        yield return new WaitForFixedUpdate();
        yield return new WaitForFixedUpdate();
        yield return new WaitForFixedUpdate();
        sb.AppendLine($"  after step: pinned={pin.Pinned}");

        var win = UnityEngine.Object.FindObjectOfType<VisionWindow>();
        foreach (var w in UnityEngine.Object.FindObjectsOfType<VisionWindow>())
            if (w.Side == PlayerSide.Left) win = w;
        sb.AppendLine($"  left window anchored={win.IsAnchored} center={win.ResolveCenter()} owner={left.transform.position}");

        // 走开，验证自动解除
        rb.position = new Vector3(-7.0f, -2.55f, 0f);
        left.transform.position = new Vector3(-7.0f, -2.55f, 0f);
        yield return new WaitForSeconds(0.7f);
        sb.AppendLine($"  after walk away: pinned={pin.Pinned} anchored={win.IsAnchored}");
    }

    // ---------- L008 未干颜料块 ----------
    session.LoadIndex(7);
    yield return null;
    yield return null;

    var crumbles = UnityEngine.Object.FindObjectsOfType<CrumblePlatform>();
    var right = FindPlayer(PlayerSide.Right);
    sb.AppendLine($"L008 loaded={session.Current?.LevelId} crumbles={crumbles.Length}");
    if (crumbles.Length > 0 && right != null)
    {
        var target = crumbles[0];
        var rb2 = right.GetComponent<Rigidbody2D>();
        Vector3 stand = target.transform.position + new Vector3(0f, 1.0f, 0f);
        rb2.position = stand;
        right.transform.position = stand;
        sb.AppendLine($"  placed at {stand}, collider before={target.GetComponent<Collider2D>().enabled}");

        yield return new WaitForSeconds(0.9f);
        sb.AppendLine($"  0.9s: isDown={target.IsDown} collider={target.GetComponent<Collider2D>().enabled}");

        yield return new WaitForSeconds(2.6f);
        sb.AppendLine($"  3.5s: isDown={target.IsDown} collider={target.GetComponent<Collider2D>().enabled}");
    }

    // ---------- L009 游动颜料团 ----------
    session.LoadIndex(8);
    yield return null;
    yield return null;

    var moving = UnityEngine.Object.FindObjectOfType<MovingPlatform>();
    sb.AppendLine($"L009 loaded={session.Current?.LevelId} moving={(moving != null)}");
    if (moving != null)
    {
        Vector3 p0 = moving.transform.position;
        yield return new WaitForSeconds(1.0f);
        Vector3 p1 = moving.transform.position;
        sb.AppendLine($"  travel 1s: {p0.x:F2} -> {p1.x:F2} (moved {Mathf.Abs(p1.x - p0.x):F2}) vel={moving.Velocity.x:F2}");

        var left2 = FindPlayer(PlayerSide.Left);
        if (left2 != null)
        {
            var rb3 = left2.GetComponent<Rigidbody2D>();
            Vector3 above = moving.transform.position + new Vector3(0f, 1.1f, 0f);
            rb3.position = above;
            left2.transform.position = above;
            yield return new WaitForSeconds(0.8f);
            float px0 = left2.transform.position.x;
            Vector3 mp0 = moving.transform.position;
            yield return new WaitForSeconds(0.8f);
            float px1 = left2.transform.position.x;
            Vector3 mp1 = moving.transform.position;
            sb.AppendLine($"  rider: player {px0:F2}->{px1:F2}, platform {mp0.x:F2}->{mp1.x:F2}, playerGrounded={left2.Grounded}");
        }
    }

    Debug.Log("[VERIFY]\n" + sb);
}

return Run();

