        var comps = new StringBuilder();
        foreach (var c in t.GetComponents<Component>())
        {
            comps.Append(c.GetType().Name).Append(' ');
            if (c is BoxCollider2D b) comps.Append($"[box {b.size} off {b.offset} trig {b.isTrigger}] ");
            if (c is CapsuleCollider2D cap) comps.Append($"[cap {cap.size} off {cap.offset} trig {cap.isTrigger}] ");
            if (c is CircleCollider2D cir) comps.Append($"[circle r{cir.radius} off {cir.offset} trig {cir.isTrigger}] ");
            if (c is Rigidbody2D rb) comps.Append($"[rb {rb.bodyType} grav {rb.gravityScale}] ");
        }
        sb.AppendLine($"{ind}{t.name} pos={t.localPosition} scale={t.localScale} :: {comps}");
        for (int i = 0; i < t.childCount; i++) Walk(t.GetChild(i), d + 1);
    }
    Walk(go.transform, 0);

    if (p.Contains("Crumble"))
    {
        var cp = go.GetComponent<CrumblePlatform>();
        var so = new SerializedObject(cp);
        foreach (var f in new[] { "standDelay", "collapseDuration", "goneDuration", "restoreDuration", "playerMask" })
        {
            var prop = so.FindProperty(f);
            sb.AppendLine($"  {f} = {(prop != null ? prop.ToString() : "MISSING")}");
        }
    }
}
return sb.ToString();

