        block.localPosition = blockBasePosition + new Vector3(shake, 0f, 0f);
    }

    if (timer < standDelay) return;

    EnterCollapsing();
}

bool PlayerOnTop()
{
    if (body == null) return false;

    Bounds bounds = body.bounds;
    Vector2 center = new Vector2(bounds.center.x, bounds.max.y + 0.1f);
    return Physics2D.OverlapBox(center, riderCheckSize, 0f, playerMask) != null;
