foreach (var file in Directory.GetFiles(dir, "*.png"))
{
    var assetPath = file.Replace('\\', '/');
    var importer = AssetImporter.GetAtPath(assetPath) as TextureImporter;
    if (importer == null) { sb.AppendLine(assetPath + " NO_IMPORTER"); continue; }

    var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    tex.LoadImage(File.ReadAllBytes(file));
    int w = tex.width, h = tex.height;
    var px = tex.GetPixels32();
    int minX = w, maxX = -1, minY = h, maxY = -1;
    for (int y = 0; y < h; y++)
    for (int x = 0; x < w; x++)
    {
        if (px[y * w + x].a < 16) continue;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }
    UnityEngine.Object.DestroyImmediate(tex);

    if (maxX < 0) { sb.AppendLine(Path.GetFileName(file) + " EMPTY"); continue; }

    importer.textureType = TextureImporterType.Sprite;
    importer.spriteImportMode = SpriteImportMode.Multiple;
    importer.spritePixelsPerUnit = 600f;
    importer.filterMode = FilterMode.Bilinear;
    importer.mipmapEnabled = false;
    importer.alphaIsTransparency = true;
    importer.wrapMode = TextureWrapMode.Clamp;

    var spriteName = Path.GetFileNameWithoutExtension(file);
    var sheet = new SpriteMetaData[1];
    sheet[0].name = spriteName;
    sheet[0].rect = new Rect(minX, minY, maxX - minX + 1, maxY - minY + 1);
    sheet[0].alignment = (int)SpriteAlignment.Center;
    sheet[0].pivot = new Vector2(0.5f, 0.5f);
    importer.spritesheet = sheet;
    importer.SaveAndReimport();

    sb.AppendLine($"{Path.GetFileName(file)} cropped={sheet[0].rect.size}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();

// 2) 重新绑定终点
Sprite LoadFirst(string path)
{
    foreach (var a in AssetDatabase.LoadAllAssetsAtPath(path))
        if (a is Sprite s) return s;
    return null;
}

void Rebind(string prefabPath, string spritePath)
{
    var sprite = LoadFirst(spritePath);
    if (sprite == null) { sb.AppendLine(prefabPath + " SPRITE_NULL"); return; }

    var root = PrefabUtility.LoadPrefabContents(prefabPath);
    var visual = root.transform.Find("Visual");
