具体实现：

```csharp
public IEnumerator DissolveRoutine()
{
    if (dissolving) yield break;
    if (dissolveMaterial == null) yield break;

    CollectTargets();
    if (targets.Count == 0) yield break;

    dissolving = true;
    runtime = new Material(dissolveMaterial);
    PrepareSeeds();

    for (int i = 0; i < targets.Count; i++)
    {
        originals.Add(targets[i].sharedMaterial);
        targets[i].sharedMaterial = runtime;
    }

    float timer = 0f;
    while (timer < 1f)
    {
        timer += Time.deltaTime / Mathf.Max(duration, 0.01f);
        UpdateRadii(Mathf.Clamp01(timer));
        yield return null;
    }

    UpdateRadii(1f);
    HideAll();
    dissolving = false;
}
```

注意 `yield return null` 后要再推一次 radii。

HideAll：恢复材质 + enabled=false，记录到 hidden 列表供 Reset。

但 originals 列表和 targets 一一对应，隐藏后需要保留以便恢复。

```csharp
readonly List<SpriteRenderer> hiddenRenderers = new List<SpriteRenderer>();
readonly List<Material> hiddenOriginals = new List<Material>();

void HideAll()
{
    for (int i = 0; i < targets.Count; i++)
    {
        var r = targets[i];
        if (r == null) continue;
        r.sharedMaterial = originals[i];
        r.enabled = false;
        hiddenRenderers.Add(r);
        hiddenOriginals.Add(originals[i]);
    }
    targets.Clear();
    originals.Clear();
}

public void ResetVisuals()
{
    for (int i = 0; i < hiddenRenderers.Count; i++)
    {
        var r = hiddenRenderers[i];
        if (r == null) continue;
        r.sharedMaterial = hiddenOriginals[i];
        r.enabled = true;
    }
    hiddenRenderers.Clear();
    hiddenOriginals.Clear();

    if (runtime != null) { Destroy(runtime); runtime = null; }
    dissolving = false;
}
```

