```csharp
void PrepareSeeds()
{
    var cam = Camera.main;
    Vector2 center = cam != null ? (Vector2)cam.transform.position : Vector2.zero;
    float halfH = cam != null ? cam.orthographicSize : 4.5f;
    float halfW = halfH * (cam != null ? cam.aspect : 16f / 9f);

    Vector2[] offsets = seedOffsets != null && seedOffsets.Length > 0
        ? seedOffsets
        : new[] { new Vector2(-halfW * 0.5f, halfH * 0.5f), ... };

    int count = Mathf.Min(offsets.Length, MaxSeeds);
    for (int i = 0; i < MaxSeeds; i++)
    {
        if (i >= count) { seeds[i] = Vector4.zero; maxRadii[i] = 0f; radii[i] = 0f; continue; }

        Vector2 p = center + offsets[i];
        seeds[i] = new Vector4(p.x, p.y, 0f, 0f);

        float max = 0f;
        for (int c = 0; c < 4; c++)
        {
            var corner = new Vector2(
                center.x + ((c & 1) == 0 ? -halfW : halfW),
                center.y + ((c & 2) == 0 ? -halfH : halfH));
            max = Mathf.Max(max, Vector2.Distance(p, corner));
        }
        maxRadii[i] = max + softness;
    }
    PushSeeds();
}
```

