using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

var report = new StringBuilder();

// 1) 擦除材质
var matPath = "Assets/Art/GrayBox/SceneDissolve.mat";
var shader = Shader.Find("GrayBox/StainDissolve");
if (shader == null) return "SHADER_MISSING";

var mat = AssetDatabase.LoadAssetAtPath<Material>(matPath);
if (mat == null)
{
    mat = new Material(shader);
    AssetDatabase.CreateAsset(mat, matPath);
}
else
{
    mat.shader = shader;
}
mat.SetFloat("_Softness", 0.6f);
mat.SetColor("_Color", Color.white);
EditorUtility.SetDirty(mat);
report.AppendLine($"material {matPath} shader={mat.shader.name}");

// 2) 场景里挂一个常驻的 SceneDissolve
var scene = EditorSceneManager.GetActiveScene();
SceneDissolve dissolve = null;
foreach (var d in UnityEngine.Object.FindObjectsOfType<SceneDissolve>())
{
    dissolve = d;
    break;
}

if (dissolve == null)
{
    var go = new GameObject("SceneDissolve");
    dissolve = go.AddComponent<SceneDissolve>();
    report.AppendLine("created SceneDissolve object");
}
else
{
    report.AppendLine("SceneDissolve already exists");
}

var so = new SerializedObject(dissolve);
so.FindProperty("dissolveMaterial").objectReferenceValue = mat;
so.ApplyModifiedPropertiesWithoutUndo();
EditorUtility.SetDirty(dissolve);

// 3) 接到 LevelSession
var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
if (session == null) return report.AppendLine("NO_LEVEL_SESSION").ToString();

var sessionSo = new SerializedObject(session);
sessionSo.FindProperty("sceneDissolve").objectReferenceValue = dissolve;
sessionSo.ApplyModifiedPropertiesWithoutUndo();
EditorUtility.SetDirty(session);

EditorSceneManager.MarkSceneDirty(scene);
var saved = EditorSceneManager.SaveScene(scene);
report.AppendLine($"linked to LevelSession, scene saved={saved}");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return report.ToString();

