using System.Collections;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var fog = UnityEngine.Object.FindObjectOfType<VisionFog>();
    var dissolve = UnityEngine.Object.FindObjectOfType<SceneDissolve>();

    yield return null;
    session.LoadIndex(0);
    yield return null;
    yield return null;

    sb.AppendLine($"start level={session.Current.LevelId} dissolveLinked={(dissolve != null)}");

    PlayerMotor2D left = null, right = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
    {
        if (p.Side == PlayerSide.Left) left = p;
        else right = p;
    }

    var goals = UnityEngine.Object.FindObjectsOfType<LevelGoal>();
    foreach (var g in goals)
    {
        var target = g.Side == PlayerSide.Left ? left : right;
        if (target == null) continue;

        var rb = target.GetComponent<Rigidbody2D>();
        rb.position = g.transform.position;
        target.transform.position = g.transform.position;
    }

    yield return new WaitForFixedUpdate();
    yield return new WaitForFixedUpdate();

    foreach (var g in goals)
    {
        bool ok = g.TryClean();
        sb.AppendLine($"  clean {g.Side} occupied={g.Occupied} ok={ok}");
    }

    int CountEnabled(bool background)
    {
        int n = 0;
        foreach (var sr in UnityEngine.Object.FindObjectsOfType<SpriteRenderer>())
        {
            if (!sr.enabled) continue;
            bool isBg = sr.sortingOrder < 0;
            if (isBg == background) n++;
        }
        return n;
    }

    yield return new WaitForSeconds(0.4f);
    sb.AppendLine($"t=0.4 fog={fog.gameObject.GetComponent<SpriteRenderer>().enabled} enabledNonBg={CountEnabled(false)} bg={CountEnabled(true)}");

    yield return new WaitForSeconds(1.8f);
    sb.AppendLine($"t=2.2 fog={fog.gameObject.GetComponent<SpriteRenderer>().enabled} dissolving={dissolve.IsDissolving} enabledNonBg={CountEnabled(false)} bg={CountEnabled(true)}");

