using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

var report = new StringBuilder();

var sprite = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Pictures/background/L18_水彩笔刷_空白画布_960x1080.png");
if (sprite == null) return "BLANK_SPRITE_MISSING";

var backdrop = GameObject.Find("Backdrop");
if (backdrop == null)
{
    // 场景里背景可能分散放置，退而求其次建一个根
    backdrop = new GameObject("Backdrop");
    report.AppendLine("created Backdrop root");
}

void EnsureBlank(string name, float x)
{
    var existing = backdrop.transform.Find(name);
    GameObject go;
    if (existing != null)
    {
        go = existing.gameObject;
        report.AppendLine(name + " exists");
    }
    else
    {
        go = new GameObject(name);
        go.transform.SetParent(backdrop.transform, false);
        report.AppendLine(name + " created");
    }

    go.transform.localPosition = new Vector3(x, 0f, 0f);
    go.transform.localScale = new Vector3(8f, 8f, 1f);

    var sr = go.GetComponent<SpriteRenderer>();
    if (sr == null) sr = go.AddComponent<SpriteRenderer>();
    sr.sprite = sprite;
    sr.sortingOrder = GrayBoxSorting.Terrain - 20;   // -20，永远在最底下
    sr.color = Color.white;
    sr.drawMode = SpriteDrawMode.Simple;

    report.AppendLine($"  {name} scale={go.transform.localScale} sort={sr.sortingOrder} world={sprite.bounds.size}");
}

EnsureBlank("CanvasBlank_Left", -4f);
EnsureBlank("CanvasBlank_Right", 4f);

// 斑驳背景也要参与擦除，所以下限放到 -10
var dissolve = UnityEngine.Object.FindObjectOfType<SceneDissolve>();
if (dissolve != null)
{
    var so = new SerializedObject(dissolve);
    so.FindProperty("minSortingOrder").intValue = -10;
    so.FindProperty("revealDuration").floatValue = 1.4f;
    so.ApplyModifiedPropertiesWithoutUndo();
    EditorUtility.SetDirty(dissolve);
    report.AppendLine("SceneDissolve minSortingOrder=-10 revealDuration=1.4");
}

var scene = EditorSceneManager.GetActiveScene();
EditorSceneManager.MarkSceneDirty(scene);
var saved = EditorSceneManager.SaveScene(scene);
report.AppendLine($"scene saved={saved}");

AssetDatabase.SaveAssets();
return report.ToString();

using System.Collections;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var fog = UnityEngine.Object.FindObjectOfType<VisionFog>();
    var fogSr = fog.GetComponent<SpriteRenderer>();
    var dissolve = UnityEngine.Object.FindObjectOfType<SceneDissolve>();

    yield return null;
    session.LoadIndex(0);

    int Count(int minSort, int maxSort)
    {
        int n = 0;
        foreach (var sr in UnityEngine.Object.FindObjectsOfType<SpriteRenderer>())
        {
            if (!sr.enabled) continue;
            if (sr.sortingOrder >= minSort && sr.sortingOrder <= maxSort) n++;
        }
        return n;
    }

    yield return null;
    sb.AppendLine($"t=0 reveal={dissolve.IsDissolving} fog={fogSr.enabled} layer>=-10:{Count(-10, 99)} blank:{Count(-20, -20)}");

    yield return new WaitForSeconds(0.7f);
    sb.AppendLine($"t=0.7 reveal={dissolve.IsDissolving} fog={fogSr.enabled} layer>=-10:{Count(-10, 99)} blank:{Count(-20, -20)}");

    yield return new WaitForSeconds(1.0f);
    sb.AppendLine($"t=1.7 reveal={dissolve.IsDissolving} fog={fogSr.enabled} layer>=-10:{Count(-10, 99)} blank:{Count(-20, -20)}");

    // 清污渍
    PlayerMotor2D left = null, right = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
    {
        if (p.Side == PlayerSide.Left) left = p;
        else right = p;
    }
    foreach (var g in UnityEngine.Object.FindObjectsOfType<LevelGoal>())
    {
        var t = g.Side == PlayerSide.Left ? left : right;
        if (t == null) continue;
        var rb = t.GetComponent<Rigidbody2D>();
        rb.position = g.transform.position;
        t.transform.position = g.transform.position;
    }
    yield return new WaitForSeconds(0.4f);
    foreach (var g in UnityEngine.Object.FindObjectsOfType<LevelGoal>()) g.TryClean();

    yield return new WaitForSeconds(1.8f);
    sb.AppendLine($"t=3.9 fog={fogSr.enabled} dissolve={dissolve.IsDissolving} layer>=-10:{Count(-10, 99)} blank:{Count(-20, -20)}");

    yield return new WaitForSeconds(1.7f);
    sb.AppendLine($"t=5.6 fog={fogSr.enabled} dissolve={dissolve.IsDissolving} layer>=-10:{Count(-10, 99)} blank:{Count(-20, -20)}");

    yield return new WaitForSeconds(2.4f);
    sb.AppendLine($"t=8.0 level={session.Current.LevelId} layer>=-10:{Count(-10, 99)} blank:{Count(-20, -20)} fog={fogSr.enabled}");

    Debug.Log("[SEQUENCE]\n" + sb);
}

return Run();

