using System.Collections;
using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 弹床：画里长着的一丛圆蘑菇。落上去会被弹到固定高度，
    /// 不消耗跳跃，所以盲跳也不用怕——轨迹每次一样。
    /// </summary>
    [RequireComponent(typeof(Collider2D))]
    public sealed class SpringBed : MonoBehaviour
    {
        [Tooltip("弹起速度，比角色正常跳跃(10.5)高才有效果")]
        [SerializeField] float bounceVelocity = 15f;

        [SerializeField] float cooldown = 0.15f;

        [Header("Visual")]
        [SerializeField] Transform visual;
        [SerializeField, Range(0.2f, 1f)] float squashScale = 0.55f;
        [SerializeField] float squashSeconds = 0.16f;

        Vector3 baseScale;
        float lastBounce = -99f;

        public MechanismKind Kind => MechanismKind.SpringBed;

        void Awake()
        {
            if (visual == null) visual = transform;
            baseScale = visual.localScale;
        }

        void Reset()
        {
            var col = GetComponent<Collider2D>();
            if (col != null) col.isTrigger = false;
        }

        void OnCollisionEnter2D(Collision2D collision)
        {
            var motor = collision.collider.GetComponentInParent<PlayerMotor2D>();
            if (motor == null) return;

            // 只认从上方落下来的
            if (motor.transform.position.y < transform.position.y) return;
            if (Time.time < lastBounce + cooldown) return;

            var body = motor.GetComponent<Rigidbody2D>();
            if (body == null) return;

            body.velocity = new Vector2(body.velocity.x, bounceVelocity);
            lastBounce = Time.time;

            StartCoroutine(SquashRoutine());
        }

        IEnumerator SquashRoutine()
        {
            float timer = 0f;
            while (timer < 1f)
            {
                timer += Time.deltaTime / Mathf.Max(squashSeconds, 0.01f);

                // 先压扁再弹回，用一个对称的三角形
                float t = Mathf.Clamp01(timer);
                float squash = t < 0.5f ? Mathf.Lerp(1f, squashScale, t * 2f) : Mathf.Lerp(squashScale, 1f, (t - 0.5f) * 2f);

                visual.localScale = new Vector3(baseScale.x, baseScale.y * squash, baseScale.z);
                yield return null;
            }

            visual.localScale = baseScale;
        }

        public void Configure(Transform newVisual, float newBounce)
        {
            visual = newVisual;
            bounceVelocity = newBounce;
            if (visual != null) baseScale = visual.localScale;
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 单块石压板。被角色站住时下沉并变色，离开后弹回。
    /// 本身不驱动任何东西，由 TandemGate 检查两块是否同时被踩。
    /// </summary>
    [RequireComponent(typeof(Collider2D))]
    public sealed class TandemPlate : MonoBehaviour
    {
        [SerializeField] Transform plate;
        [SerializeField] SpriteRenderer visual;
        [SerializeField] float sinkDepth = 0.07f;
        [SerializeField] Color idleColor = Color.white;
        [SerializeField] Color pressedColor = new Color(0.72f, 0.78f, 0.84f, 1f);
        [SerializeField] float sinkSeconds = 0.1f;

        int occupants;
        Vector3 basePosition;
        float sink;

        public MechanismKind Kind => MechanismKind.TandemPlate;
        public bool Pressed => occupants > 0;

        void Awake()
        {
            if (plate == null) plate = transform;
            if (visual == null) visual = GetComponentInChildren<SpriteRenderer>();

            basePosition = plate.localPosition;
        }

        void Reset()
        {
            var col = GetComponent<Collider2D>();
            if (col != null) col.isTrigger = true;
        }

        void OnTriggerEnter2D(Collider2D other)
        {
            if (other.GetComponentInParent<PlayerMotor2D>() == null) return;

            occupants++;
        }

        void OnTriggerExit2D(Collider2D other)
        {
            if (other.GetComponentInParent<PlayerMotor2D>() == null) return;

            occupants = Mathf.Max(0, occupants - 1);
        }

        void Update()
        {
            float target = Pressed ? 1f : 0f;
            sink = Mathf.MoveTowards(sink, target, Time.deltaTime / Mathf.Max(sinkSeconds, 0.01f));

            if (plate != null)
                plate.localPosition = basePosition + Vector3.down * (sinkDepth * sink);

            if (visual != null)
                visual.color = Color.Lerp(idleColor, pressedColor, sink);
        }

        public void Configure(Transform newPlate, SpriteRenderer newVisual)
        {
            plate = newPlate;
            visual = newVisual;
            if (plate != null) basePosition = plate.localPosition;
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 双压板的总闸：两块石压板都被人踩住时，才驱动相连的 ISwitchTarget。
    /// 两块通常分在左右半屏，逼两个人分头行动——而他们互相看不见。
    /// </summary>
    public sealed class TandemGate : MonoBehaviour
    {
        [SerializeField] TandemPlate plateA;
        [SerializeField] TandemPlate plateB;

        [Tooltip("挂任意实现了 ISwitchTarget 的组件")]
        [SerializeField] MonoBehaviour[] targets;

        bool open;

        public MechanismKind Kind => MechanismKind.TandemPlate;
        public bool Open => open;

        void Update()
        {
            bool both = plateA != null && plateB != null && plateA.Pressed && plateB.Pressed;
            if (both == open) return;

            open = both;
            Apply(open);
        }

        void OnDisable()
        {
            if (!open) return;

            open = false;
            Apply(false);
        }

        void Apply(bool value)
        {
            if (targets == null) return;

            foreach (var target in targets)
            {
                if (target is ISwitchTarget switchTarget) switchTarget.SetActive(value);
            }
        }

        public void Configure(TandemPlate a, TandemPlate b, MonoBehaviour[] newTargets)
        {
            plateA = a;
            plateB = b;
            targets = newTargets;
        }
    }
}

using UnityEngine;

namespace ThreeCup.GrayBox
{
    /// <summary>
    /// 透镜（露珠）：画里草叶上凝着的一滴水。踩一下让透光口放大，
    /// 再踩缩成一小块，第三次恢复。放大看得远但对面近端会漏掉，
    /// 缩小看得窄但落点更准。
    /// </summary>
    [RequireComponent(typeof(Collider2D))]
    public sealed class LensStation : MonoBehaviour
    {
        enum Mode { Normal, ZoomIn, ZoomOut }

        [SerializeField] PlayerSide side = PlayerSide.Left;

        [Header("Zoom")]
        [Tooltip("放大时的视窗尺寸倍率与偏移倍率")]
        [SerializeField] Vector2 zoomInScale = new Vector2(1.7f, 1.3f);

        [Tooltip("缩小时的视窗尺寸倍率与偏移倍率")]
        [SerializeField] Vector2 zoomOutScale = new Vector2(0.55f, 0.7f);

        [Header("Visual")]
        [SerializeField] SpriteRenderer visual;
        [SerializeField] Color normalColor = Color.white;
        [SerializeField] Color zoomInColor = new Color(0.70f, 0.86f, 1f, 1f);
        [SerializeField] Color zoomOutColor = new Color(0.78f, 1f, 0.84f, 1f);

        Mode mode;
        VisionWindow window;

        public MechanismKind Kind => MechanismKind.Lens;
        public PlayerSide Side => side;

        void Reset()
        {
            var col = GetComponent<Collider2D>();
            if (col != null) col.isTrigger = true;
        }

        void Awake()
        {
            if (visual == null) visual = GetComponentInChildren<SpriteRenderer>();
        }

        void OnTriggerEnter2D(Collider2D other)
        {
            var motor = other.GetComponentInParent<PlayerMotor2D>();
            if (motor == null || motor.Side != side) return;

            EnsureWindow();
            if (window == null) return;

            mode = mode == Mode.Normal ? Mode.ZoomIn
                 : mode == Mode.ZoomIn ? Mode.ZoomOut
                 : Mode.Normal;

            Apply();
        }

        void Apply()
        {
            if (window != null)
            {
                switch (mode)
                {
                    case Mode.ZoomIn:
                        window.SetZoom(zoomInScale.x, zoomInScale.y);
                        break;
                    case Mode.ZoomOut:
                        window.SetZoom(zoomOutScale.x, zoomOutScale.y);
                        break;
                    default:
                        window.SetZoom(1f, 1f);
                        break;
                }
            }

            if (visual == null) return;

            visual.color = mode == Mode.ZoomIn ? zoomInColor
                         : mode == Mode.ZoomOut ? zoomOutColor
                         : normalColor;
        }

        void EnsureWindow()
        {
            if (window != null) return;

            foreach (var candidate in FindObjectsOfType<VisionWindow>())
            {
                if (candidate.Side != side) continue;

                window = candidate;
                return;
            }
        }

        void OnDisable()
        {
            if (window != null) window.SetZoom(1f, 1f);
        }

        public void Configure(PlayerSide newSide, SpriteRenderer newVisual)
        {
            side = newSide;
            visual = newVisual;
        }
    }
}

