using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;

var report = new StringBuilder();

var defs = new (string name, float ppu)[]
{
    ("13_露珠", 340f),
    ("14_圆蘑菇", 375f),
    ("15_石压板", 500f)
};

foreach (var (name, ppu) in defs)
{
    var path = "Assets/Pictures/" + name + ".png";
    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
    if (importer == null) { report.AppendLine(path + " NO_IMPORTER"); continue; }

    var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
    tex.LoadImage(File.ReadAllBytes(path));
    int w = tex.width, h = tex.height;
    var px = tex.GetPixels32();
    int minX = w, maxX = -1, minY = h, maxY = -1;
    for (int y = 0; y < h; y++)
    for (int x = 0; x < w; x++)
    {
        if (px[y * w + x].a < 16) continue;
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }
    UnityEngine.Object.DestroyImmediate(tex);

    importer.textureType = TextureImporterType.Sprite;
    importer.spriteImportMode = SpriteImportMode.Multiple;
    importer.spritePixelsPerUnit = ppu;
    importer.filterMode = FilterMode.Bilinear;
    importer.mipmapEnabled = false;
    importer.alphaIsTransparency = true;
    importer.wrapMode = TextureWrapMode.Clamp;

    var sheet = new SpriteMetaData[1];
    sheet[0].name = name;
    sheet[0].rect = new Rect(minX, minY, maxX - minX + 1, maxY - minY + 1);
    sheet[0].alignment = (int)SpriteAlignment.Center;
    sheet[0].pivot = new Vector2(0.5f, 0.5f);
    importer.spritesheet = sheet;
    importer.SaveAndReimport();

    report.AppendLine($"{name}: crop={sheet[0].rect.size} ppu={ppu}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return report.ToString();

