using System.Collections;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    yield return null;

    session.LoadIndex(10);
    yield return new WaitForSeconds(2.8f);
    sb.AppendLine($"L011 loaded={session.Current?.LevelId}");

    PlayerMotor2D left = null, right = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
    {
        if (p.Side == PlayerSide.Left) left = p;
        else right = p;
    }
    var lrb = left.GetComponent<Rigidbody2D>();
    var rrb = right.GetComponent<Rigidbody2D>();

    VisionWindow leftWin = null;
    foreach (var w in UnityEngine.Object.FindObjectsOfType<VisionWindow>())
        if (w.Side == PlayerSide.Left) leftWin = w;

    // ---- 1. 露珠 ----
    sb.AppendLine($"lens before: size={leftWin.PrimarySize}");
    lrb.position = new Vector3(-5.0f, -2.6f, 0f);
    left.transform.position = new Vector3(-5.0f, -2.6f, 0f);
    yield return new WaitForSeconds(0.35f);
    sb.AppendLine($"lens after 1 step: size={leftWin.PrimarySize}");
    lrb.position = new Vector3(-5.0f, -2.6f, 0f);
    left.transform.position = new Vector3(-5.0f, -2.6f, 0f);
    yield return new WaitForSeconds(0.35f);
    sb.AppendLine($"lens after 2 steps: size={leftWin.PrimarySize}");
    lrb.position = new Vector3(-5.0f, -2.6f, 0f);
    left.transform.position = new Vector3(-5.0f, -2.6f, 0f);
    yield return new WaitForSeconds(0.35f);
    sb.AppendLine($"lens after 3 steps: size={leftWin.PrimarySize}");

    // ---- 2. 蘑菇 ----
    lrb.position = new Vector3(-7.0f, -2.55f, 0f);
    left.transform.position = new Vector3(-7.0f, -2.55f, 0f);

    Vector3 aboveMushroom = new Vector3(2.8f, -1.8f, 0f);
    rrb.position = aboveMushroom;
    right.transform.position = aboveMushroom;

    float maxUp = 0f;
    for (int i = 0; i < 20; i++)
    {
        yield return new WaitForFixedUpdate();
        float v = rrb.velocity.y;
        if (v > maxUp) maxUp = v;
    }
    sb.AppendLine($"spring: maxUpVelocity={maxUp:F2} (expect > 10) y={right.transform.position.y:F2}");

    // ---- 3. 升降台 ----
    rrb.position = new Vector3(4.6f, -2.9f, 0f);
    right.transform.position = new Vector3(4.6f, -2.9f, 0f);
    yield return new WaitForSeconds(0.3f);
    float y0 = right.transform.position.y;
    yield return new WaitForSeconds(1.4f);
    float y1 = right.transform.position.y;
    sb.AppendLine($"lift: playerY {y0:F2} -> {y1:F2} (expect rise)");

    // ---- 4. 双压板 ----
    lrb.position = new Vector3(-1.8f, -2.45f, 0f);
    left.transform.position = new Vector3(-1.8f, -2.45f, 0f);
    rrb.position = new Vector3(6.6f, -2.45f, 0f);
    right.transform.position = new Vector3(6.6f, -2.45f, 0f);
    yield return new WaitForSeconds(0.4f);

    var gate = UnityEngine.Object.FindObjectOfType<TandemGate>();
    var bridge = GameObject.Find("Bridge");
    sb.AppendLine($"tandem: gate={(gate != null)} open={(gate != null && gate.Open)} bridgeCollider={(bridge != null ? bridge.GetComponent<Collider2D>().enabled.ToString() : "NO_BRIDGE")}");

    Debug.Log("[NEW_MECHS]\n" + sb);
}

return Run();

