IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    yield return null;

    session.LoadIndex(10);
    yield return new WaitForSeconds(2.8f);

    PlayerMotor2D left = null, right = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
    {
        if (p.Side == PlayerSide.Left) left = p;
        else right = p;
    }
    var lrb = left.GetComponent<Rigidbody2D>();
    var rrb = right.GetComponent<Rigidbody2D>();

    VisionWindow leftWin = null;
    foreach (var w in UnityEngine.Object.FindObjectsOfType<VisionWindow>())
        if (w.Side == PlayerSide.Left) leftWin = w;

    IEnumerator StepLens(string label)
    {
        lrb.position = new Vector3(-5.0f, -2.6f, 0f);
        left.transform.position = new Vector3(-5.0f, -2.6f, 0f);
        yield return new WaitForSeconds(0.25f);
        sb.AppendLine($"lens {label}: size={leftWin.PrimarySize} center={leftWin.ResolveCenter()}");

        lrb.position = new Vector3(-7.0f, -2.55f, 0f);
        left.transform.position = new Vector3(-7.0f, -2.55f, 0f);
        yield return new WaitForSeconds(0.25f);
    }

    yield return StepLens("step1");
    yield return StepLens("step2");
    yield return StepLens("step3");
    yield return StepLens("step4");

    // 蘑菇：直接放在上方，逐帧采样
    lrb.position = new Vector3(-7.0f, -2.55f, 0f);
    left.transform.position = new Vector3(-7.0f, -2.55f, 0f);

    Vector3 start = new Vector3(2.8f, -2.1f, 0f);
    rrb.position = start;
    right.transform.position = start;

    float maxUp = -99f;
    float minY = 99f;
    for (int i = 0; i < 60; i++)
    {
        yield return null;
        if (rrb.velocity.y > maxUp) maxUp = rrb.velocity.y;
        if (right.transform.position.y < minY) minY = right.transform.position.y;
    }
    sb.AppendLine($"spring: maxUp={maxUp:F2} minY={minY:F2} endY={right.transform.position.y:F2}");

    Debug.Log("[RECHECK_MECHS]\n" + sb);
}

return Run();

