using System.Collections.Generic;
using System.Text;
using UnityEditor;
using UnityEngine;

// 收集所有会引用图片的资源
var owners = new List<string>();
foreach (var p in AssetDatabase.GetAllAssetPaths())
{
    if (!p.StartsWith("Assets/")) continue;
    if (p.EndsWith(".prefab") || p.EndsWith(".unity") || p.EndsWith(".asset") || p.EndsWith(".mat") || p.EndsWith(".controller"))
        owners.Add(p);
}

// 图片 -> 引用它的资源列表
var refs = new Dictionary<string, List<string>>();
foreach (var owner in owners)
{
    foreach (var dep in AssetDatabase.GetDependencies(owner, true))
    {
        if (!dep.EndsWith(".png")) continue;
        if (!refs.TryGetValue(dep, out var list))
        {
            list = new List<string>();
            refs[dep] = list;
        }
        if (!list.Contains(owner)) list.Add(owner);
    }
}

var sb = new StringBuilder();
var unused = new StringBuilder();

foreach (var png in AssetDatabase.FindAssets("t:Texture2D", new[] { "Assets/Pictures" }))
{
    var path = AssetDatabase.GUIDToAssetPath(png);
    if (!path.EndsWith(".png")) continue;

    if (refs.TryGetValue(path, out var list) && list.Count > 0)
    {
        sb.AppendLine($"[USED] {path}");
        for (int i = 0; i < list.Count && i < 3; i++)
            sb.AppendLine($"        <- {list[i]}");
        if (list.Count > 3) sb.AppendLine($"        <- ...共 {list.Count} 处");
    }
    else
    {
        sb.AppendLine($"[UNUSED] {path}");
        unused.AppendLine(path);
    }
}

return sb.ToString();

