using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEngine;

Sprite LoadSprite(string path)
{
    foreach (var a in AssetDatabase.LoadAllAssetsAtPath(path))
        if (a is Sprite s) return s;
    return null;
}

var report = new StringBuilder();
var lamp = LoadSprite("Assets/Pictures/16_油灯.png");
if (lamp == null) return "LAMP_SPRITE_MISSING";

// 预制体
var root = new GameObject("Beacon_Lamp");
var sr = root.AddComponent<SpriteRenderer>();
sr.sprite = lamp;
sr.sortingOrder = GrayBoxSorting.Hint;

var col = root.AddComponent<BoxCollider2D>();
col.isTrigger = true;
col.size = new Vector2(0.5f, 0.9f);

var beacon = root.AddComponent<BeaconSwitch>();
beacon.Configure(new Vector2(3.4f, 2.2f), true, sr);

var prefabPath = "Assets/Prefabs/GrayBox/Mechanisms/Beacon_Lamp.prefab";
PrefabUtility.SaveAsPrefabAsset(root, prefabPath);
UnityEngine.Object.DestroyImmediate(root);
report.AppendLine($"prefab {prefabPath} lamp={lamp.bounds.size}");

// L006 放一盏灯（左半屏，镜像点亮右侧两根隐藏柱）
var l006Path = "Assets/Prefabs/GrayBox/L006.prefab";
var l006 = PrefabUtility.LoadPrefabContents(l006Path);
var mechs = l006.transform.Find("Mechanisms");
if (mechs == null)
{
    var go = new GameObject("Mechanisms");
    go.transform.SetParent(l006.transform, false);
    mechs = go.transform;
}

var existing = mechs.Find("Beacon_Left");
if (existing != null) UnityEngine.Object.DestroyImmediate(existing.gameObject);

var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
var inst = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
inst.name = "Beacon_Left";
inst.transform.SetParent(mechs, false);
inst.transform.localPosition = new Vector3(-3.6f, -2.54f, 0f);

PrefabUtility.SaveAsPrefabAsset(l006, l006Path);
PrefabUtility.UnloadPrefabContents(l006);
report.AppendLine("L006 Beacon_Left at (-3.6, -2.54)");

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return report.ToString();

using System.Collections;
using System.Collections.Generic;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var fog = UnityEngine.Object.FindObjectOfType<VisionFog>();
    var fogSr = fog.GetComponent<SpriteRenderer>();
    var mpb = new MaterialPropertyBlock();

    yield return null;
    session.LoadIndex(5);
    yield return new WaitForSeconds(2.8f);

    var beacon = UnityEngine.Object.FindObjectOfType<BeaconSwitch>();
    sb.AppendLine($"L006 beacon={(beacon != null)} lit={(beacon != null && beacon.Lit)} center={(beacon != null ? beacon.HoleCenter.ToString() : "-")}");

    PlayerMotor2D left = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
        if (p.Side == PlayerSide.Left) left = p;

    var rb = left.GetComponent<Rigidbody2D>();

    // 踩上灯
    rb.position = new Vector3(-3.6f, -2.54f, 0f);
    left.transform.position = new Vector3(-3.6f, -2.54f, 0f);
    yield return new WaitForSeconds(0.35f);

    var holes = new List<Vector4>();
    fogSr.GetPropertyBlock(mpb);
    mpb.GetVectorArray("_Holes", holes);
    sb.AppendLine($"after step: lit={beacon.Lit} holes[0]={(holes.Count > 0 ? holes[0].ToString() : "-")}");

    // 走开再回来，熄灭
    rb.position = new Vector3(-6.5f, -2.55f, 0f);
    left.transform.position = new Vector3(-6.5f, -2.55f, 0f);
    yield return new WaitForSeconds(0.3f);
    rb.position = new Vector3(-3.6f, -2.54f, 0f);
    left.transform.position = new Vector3(-3.6f, -2.54f, 0f);
    yield return new WaitForSeconds(0.35f);

    fogSr.GetPropertyBlock(mpb);
    mpb.GetVectorArray("_Holes", holes);
    sb.AppendLine($"after second step: lit={beacon.Lit} holes[0]={(holes.Count > 0 ? holes[0].ToString() : "-")}");

    Debug.Log("[BEACON]\n" + sb);
}

return Run();

