var report = new StringBuilder();

// 1) L005 桥面高度对齐到 Plat_L2 顶面 -1.8
var l005Path = "Assets/Prefabs/GrayBox/L005.prefab";
var l005 = PrefabUtility.LoadPrefabContents(l005Path);
