[Header("Grow")]
[SerializeField] float growSeconds = 0.35f;
[SerializeField] bool growFromLeft = true;

Vector3 baseScale;
Vector3 basePosition;
float grow;

void Awake()
{
    sprite = ...; body = ...;
    baseScale = transform.localScale;
    basePosition = transform.localPosition;
    ApplyImmediate(startActive);
}

void ApplyImmediate(bool active)
{
    Active = active;
    grow = active ? 1f : 0f;
    ApplyGrow();
}

void Update()
{
    float target = Active ? 1f : 0f;
    if (Mathf.Approximately(grow, target)) return;
    grow = Mathf.MoveTowards(grow, target, Time.deltaTime / Mathf.Max(growSeconds, 0.01f));
    ApplyGrow();
}

void ApplyGrow()
{
    if (grow <= 0.001f)
    {
        transform.localScale = baseScale;
        transform.localPosition = basePosition;
        if (sprite != null) sprite.enabled = false;
        if (body != null) body.enabled = false;
        return;
    }

    float width = baseScale.x * grow;
    transform.localScale = new Vector3(width, baseScale.y, baseScale.z);

    float shift = baseScale.x * (1f - grow) * 0.5f;
    transform.localPosition = basePosition + new Vector3(growFromLeft ? -shift : shift, 0f, 0f);

    if (body != null) body.enabled = Active;
    if (sprite != null)
    {
        sprite.enabled = Active || visibleWhenInactive;
        sprite.color = Active ? activeColor : inactiveColor;
    }
}

public void SetActive(bool active)
{
    if (Active == active) return;
    Active = active;
    if (body != null) body.enabled = active;
}
