    {
        if (!sr.enabled) continue;
        if (sr.sortingOrder == -20) blank++;
        else if (sr.sortingOrder == -10) backdrop++;
    }
    sb.AppendLine($"blank={blank} backdrop={backdrop} fog={fog.GetComponent<SpriteRenderer>().enabled} fogSprite={fog.GetComponent<SpriteRenderer>().sprite.name}");

