    yield return new WaitForSeconds(2.0f);
    sb.AppendLine($"t+2.0 dissolve={dissolve.IsDissolving} fog={fog.GetComponent<SpriteRenderer>().enabled}");

    yield return new WaitForSeconds(3.0f);
    int nonBg = 0;
    foreach (var sr in UnityEngine.Object.FindObjectsOfType<SpriteRenderer>())
        if (sr.enabled && sr.sortingOrder >= -10) nonBg++;
    sb.AppendLine($"t+5.0 level={session.Current?.LevelId} nonBgEnabled={nonBg} blank={blank}");

    Debug.Log("[YSQ_SYNC]\n" + sb);
}

