GameObject Clone(GameObject source, string name, bool keepPrefabLink)
{
    if (source == null) return null;

    GameObject clone;
    if (keepPrefabLink)
    {
        var asset = PrefabUtility.GetCorrespondingObjectFromSource(source) as GameObject;
        clone = asset != null
            ? (GameObject)PrefabUtility.InstantiatePrefab(asset)
            : UnityEngine.Object.Instantiate(source);
