        var nameProp = so.FindProperty("levelNameText")?.objectReferenceValue as Text;
        var idProp = so.FindProperty("levelIdText")?.objectReferenceValue as Text;
        var dropsRoot = so.FindProperty("dropsRoot")?.objectReferenceValue as Transform;

        sb.AppendLine($"  levelName={(nameProp != null ? nameProp.text : "NULL")}");
        sb.AppendLine($"  levelId={(idProp != null ? idProp.text : "NULL")}");
        sb.AppendLine($"  drops={dropsRoot?.childCount}");
    }

    var pause = UnityEngine.Object.FindObjectOfType<PauseMenu>();
    sb.AppendLine($"PauseMenu={(pause != null)}");
    if (pause != null)
    {
        var body = pause.transform.Find("PausePanel");
        sb.AppendLine($"  PausePanel visible={(body != null && body.gameObject.activeSelf)}");
    }

    var es = UnityEngine.Object.FindObjectOfType<UnityEngine.EventSystems.EventSystem>();
    sb.AppendLine($"EventSystem={(es != null)}");

    foreach (var canvas in UnityEngine.Object.FindObjectsOfType<Canvas>())
        sb.AppendLine($"  canvas {canvas.name} order={canvas.sortingOrder}");

    Debug.Log("[LHJ_UI]\n" + sb);
}

return Run();

