using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    var system = UnityEngine.Object.FindObjectOfType<FootprintSystem>();

    yield return null;
    yield return new WaitForSeconds(3.0f);

    sb.AppendLine($"scene={UnityEngine.SceneManagement.SceneManager.GetActiveScene().name} system={(system != null)}");

    int CountVisible()
    {
        int n = 0;
        foreach (var sr in UnityEngine.Object.FindObjectsOfType<SpriteRenderer>())
            if (sr.name.StartsWith("Footprint_") && sr.enabled && sr.color.a > 0.001f) n++;
        return n;
    }

    float MaxAlpha()
    {
        float a = 0f;
        foreach (var sr in UnityEngine.Object.FindObjectsOfType<SpriteRenderer>())
            if (sr.name.StartsWith("Footprint_") && sr.enabled && sr.color.a > a) a = sr.color.a;
        return a;
    }

    sb.AppendLine($"start: visible={CountVisible()} maxAlpha={MaxAlpha():F3}");

    PlayerMotor2D left = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
        if (p.Side == PlayerSide.Left) left = p;
    var rb = left.GetComponent<Rigidbody2D>();

    // 走动 1.6 秒
    float t = 0f;
    while (t < 1.6f)
    {
        rb.position += new Vector2(0.09f, 0f);
        left.transform.position = rb.position;
        t += Time.deltaTime;
        yield return null;
    }
    sb.AppendLine($"after walk: visible={CountVisible()} maxAlpha={MaxAlpha():F3}");

    // 原地站 1.6 秒
    yield return new WaitForSeconds(1.6f);
    sb.AppendLine($"after stand: visible={CountVisible()} maxAlpha={MaxAlpha():F3}");

    // 瞬移走开，等 3 秒
    rb.position = new Vector3(-7.3f, -2.55f, 0f);
    left.transform.position = new Vector3(-7.3f, -2.55f, 0f);
    yield return new WaitForSeconds(3.2f);
    sb.AppendLine($"after leaving 3.2s: visible={CountVisible()} maxAlpha={MaxAlpha():F3}");

    Debug.Log("[FOOTPRINT]\n" + sb);
}

return Run();

