    if (n == 0) { sb.AppendLine(name + " EMPTY"); continue; }
    sb.AppendLine($"{name}: avg=({r / n / 255f:F3}, {g / n / 255f:F3}, {b / n / 255f:F3}) pixels={n}");
}
return sb.ToString();

