using UnityEngine.SceneManagement;
using UnityEngine.UI;

var report = new StringBuilder();

var font = AssetDatabase.LoadAssetAtPath<Font>("Assets/Resources/Fonts/Chusung.ttf");
if (font == null) return "FONT_MISSING";

int ApplyTo(GameObject root)
{
    int n = 0;
    foreach (var text in root.GetComponentsInChildren<Text>(true))
    {
        if (text.font == font) continue;
        text.font = font;
        n++;
    }
    return n;
}

// 1) UI prefabs
foreach (var path in new[]
{
    "Assets/Prefabs/UI/DeathPopup.prefab",
    "Assets/Prefabs/UI/FailPopup.prefab",
    "Assets/Prefabs/UI/PauseMenu.prefab",
    "Assets/Prefabs/UI/SettingsPanel.prefab"
})
{
    var root = PrefabUtility.LoadPrefabContents(path);
    if (root == null) { report.AppendLine(path + " LOAD_FAIL"); continue; }

    int changed = ApplyTo(root);
    PrefabUtility.SaveAsPrefabAsset(root, path);
    PrefabUtility.UnloadPrefabContents(root);
    report.AppendLine($"prefab {path}: changed={changed}");
}

// 2) scenes
var active = SceneManager.GetActiveScene();
foreach (var path in new[]
{
    "Assets/Scenes/LHJ_TestScene.unity",
    "Assets/Scenes/YSQ_TestScene.unity",
    "Assets/Scenes/Start.unity",
    "Assets/Scenes/Select.unity",
    "Assets/Scenes/SampleScene.unity"
})
{
    if (!System.IO.File.Exists(path)) { report.AppendLine(path + " MISSING"); continue; }

    bool isActive = path == active.path;
    var scene = isActive ? active : EditorSceneManager.OpenScene(path, OpenSceneMode.Additive);

    int changed = 0;
    foreach (var root in scene.GetRootGameObjects())
        changed += ApplyTo(root);

    EditorSceneManager.MarkSceneDirty(scene);
    EditorSceneManager.SaveScene(scene);
    if (!isActive) EditorSceneManager.CloseScene(scene, true);

    report.AppendLine($"scene {path}: changed={changed}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return report.ToString();

