using System.Text;
using UnityEditor;
using UnityEngine;

var report = new StringBuilder();

// 1) 玩家缩小：0.8 -> 0.64
foreach (var path in new[]
{
    "Assets/Prefabs/GrayBox/Player/Player_Left.prefab",
    "Assets/Prefabs/GrayBox/Player/Player_Right.prefab"
})
{
    var root = PrefabUtility.LoadPrefabContents(path);
    root.transform.localScale = new Vector3(0.64f, 0.64f, 0.64f);
    PrefabUtility.SaveAsPrefabAsset(root, path);
    PrefabUtility.UnloadPrefabContents(root);
    report.AppendLine($"{path}: scale 0.8 -> 0.64");
}

// 2) 所有 tile 每块 0.8 -> 0.64（PPU ×1.25）
foreach (var name in new[]
{
    "sq_01_ochre_square_soft",
    "sq_02_ochre_square_crisp",
    "sq_03_sage_square",
    "sq_05_blue_square",
    "sq_07_verm_square_crisp"
})
{
    var path = "Assets/Tiles/" + name + ".png";
    var importer = AssetImporter.GetAtPath(path) as TextureImporter;
    if (importer == null) { report.AppendLine(path + " NO_IMPORTER"); continue; }

    float before = importer.spritePixelsPerUnit;
    importer.spritePixelsPerUnit = before * 1.25f;
    importer.SaveAndReimport();

    var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(path);
    report.AppendLine($"{name}: ppu {before:F1} -> {importer.spritePixelsPerUnit:F1} world={sprite.bounds.size}");
}

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
return report.ToString();

using System.Collections;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    yield return null;

    session.LoadIndex(3);
    yield return null;

    PlayerMotor2D left = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
        if (p.Side == PlayerSide.Left) left = p;

    var highlight = left.transform.Find("Highlight");

    yield return new WaitForSeconds(0.5f);
    sb.AppendLine($"reveal中: isRevealing={session.IsRevealing} highlightActive={(highlight != null && highlight.gameObject.activeSelf)} playerScale={left.transform.localScale.x:F2}");

    yield return new WaitForSeconds(2.4f);
    sb.AppendLine($"reveal后: isRevealing={session.IsRevealing} highlightActive={(highlight != null && highlight.gameObject.activeSelf)}");

    Debug.Log("[HIGHLIGHT_FIX]\n" + sb);
}

return Run();

