using System.Collections.Generic;
using System.IO;
using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

var report = new StringBuilder();

var platPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Platform.prefab");
var goalLeftPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Goal_Left.prefab");
var goalRightPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Goal_Right.prefab");
var spikePrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Spike.prefab");
var switchPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/Switch.prefab");
var togglePrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/GrayBox/Mechanisms/ToggleBlock.prefab");

if (platPrefab == null || goalLeftPrefab == null || goalRightPrefab == null
    || spikePrefab == null || switchPrefab == null || togglePrefab == null)
    return "MISSING_PREFAB";

string Build(string name, System.Action<Scene, Transform, Transform, Transform, Transform> body)
{
    var scene = EditorSceneManager.NewPreviewScene();
    var root = new GameObject(name);
    EditorSceneManager.MoveGameObjectToScene(root, scene);

    Transform Group(string groupName, Transform parent)
    {
        var go = new GameObject(groupName);
        go.transform.SetParent(parent, false);
        return go.transform;
    }

    var terrain = Group("Terrain", root.transform);
    var goals = Group("Goals", root.transform);
    var mechs = Group("Mechanisms", root.transform);

    body(scene, root.transform, terrain, goals, mechs);

    var path = "Assets/Prefabs/GrayBox/" + name + ".prefab";
    PrefabUtility.SaveAsPrefabAsset(root, path);
    EditorSceneManager.ClosePreviewScene(scene);
    return path;
}

// 通用工具
Scene currentScene;
GameObject Spawn(GameObject prefab, Transform parent, string name, Vector2 pos)
{
    var go = (GameObject)PrefabUtility.InstantiatePrefab(prefab, currentScene);
    go.name = name;
    go.transform.SetParent(parent, false);
    go.transform.localPosition = new Vector3(pos.x, pos.y, 0f);
    return go;
}

void Platform(Transform terrain, string name, Vector2 center, Vector2 size)
{
    var go = Spawn(platPrefab, terrain, name, center);
    var sr = go.GetComponent<SpriteRenderer>();
    sr.drawMode = SpriteDrawMode.Tiled;
    sr.tileMode = SpriteTileMode.Continuous;
    sr.size = size;
    go.GetComponent<BoxCollider2D>().size = size;
}

void Marker(Transform parent, string name, Vector2 pos)
{
    var go = new GameObject(name);
    go.transform.SetParent(parent, false);
    go.transform.localPosition = new Vector3(pos.x, pos.y, 0f);
}

void Goals(Transform goals, float leftX, float rightX)
{
    Spawn(goalLeftPrefab, goals, "Goal_Left", new Vector2(leftX, -2.1f));
    Spawn(goalRightPrefab, goals, "Goal_Right", new Vector2(rightX, -2.1f));
}

// ---------- T01 基础：移动 / 视窗 / 跳坑 / 清污渍 ----------
var t01Path = Build("T001", (scene, root, terrain, goals, mechs) =>
{
    currentScene = scene;
    Platform(terrain, "Plat_L1", new Vector2(-6.3f, -3.4f), new Vector2(3.4f, 0.8f));
    Platform(terrain, "Plat_L2", new Vector2(-1.7f, -3.4f), new Vector2(3.4f, 0.8f));
    Platform(terrain, "Plat_R1", new Vector2(1.7f, -3.4f), new Vector2(3.4f, 0.8f));
    Platform(terrain, "Plat_R2", new Vector2(6.3f, -3.4f), new Vector2(3.4f, 0.8f));
    Goals(goals, -2.0f, 2.0f);
    Marker(root, "Spawn_Left", new Vector2(-7.3f, -2.68f));
    Marker(root, "Spawn_Right", new Vector2(7.3f, -2.68f));
});
report.AppendLine(t01Path);

// ---------- T02 颜料罐 + 补笔带 ----------
var t02Path = Build("T002", (scene, root, terrain, goals, mechs) =>
{
    currentScene = scene;
    Platform(terrain, "Plat_L1", new Vector2(-6.5f, -3.4f), new Vector2(3.0f, 0.8f));
    Platform(terrain, "Plat_L2", new Vector2(-1.25f, -3.4f), new Vector2(2.5f, 0.8f));
    Platform(terrain, "Plat_R1", new Vector2(1.25f, -3.4f), new Vector2(2.5f, 0.8f));
    Platform(terrain, "Plat_R2", new Vector2(6.5f, -3.4f), new Vector2(3.0f, 0.8f));

    var bridgeL = Spawn(togglePrefab, mechs, "Bridge_Left", new Vector2(-3.75f, -3.355f));
    var bridgeR = Spawn(togglePrefab, mechs, "Bridge_Right", new Vector2(3.75f, -3.355f));

    foreach (var go in new[] { bridgeL, bridgeR })
    {
        go.transform.localScale = new Vector3(0.69f, 1f, 1f);
        var toggle = go.GetComponent<ToggleBlock>();
        var so = new SerializedObject(toggle);
        so.FindProperty("startActive").boolValue = false;
        so.ApplyModifiedPropertiesWithoutUndo();
    }

    var swL = Spawn(switchPrefab, mechs, "Switch_Left", new Vector2(-6.5f, -2.5f));
    var swR = Spawn(switchPrefab, mechs, "Switch_Right", new Vector2(6.5f, -2.5f));
    swL.GetComponent<Switch>().Configure(new MonoBehaviour[] { bridgeL.GetComponent<ToggleBlock>() }, true, false);
    swR.GetComponent<Switch>().Configure(new MonoBehaviour[] { bridgeR.GetComponent<ToggleBlock>() }, true, false);

    Goals(goals, -1.2f, 1.2f);
    Marker(root, "Spawn_Left", new Vector2(-7.5f, -2.68f));
    Marker(root, "Spawn_Right", new Vector2(7.5f, -2.68f));
});
report.AppendLine(t02Path);

// ---------- T03 尖刺 ----------
var t03Path = Build("T003", (scene, root, terrain, goals, mechs) =>
{
    currentScene = scene;
    Platform(terrain, "Plat_L1", new Vector2(-4.0f, -3.4f), new Vector2(7.6f, 0.8f));
    Platform(terrain, "Plat_R1", new Vector2(4.0f, -3.4f), new Vector2(7.6f, 0.8f));
    Spawn(spikePrefab, mechs, "Spike_Left", new Vector2(-5.0f, -2.76f));
    Spawn(spikePrefab, mechs, "Spike_Right", new Vector2(5.0f, -2.76f));
    Goals(goals, -2.0f, 2.0f);
    Marker(root, "Spawn_Left", new Vector2(-7.0f, -2.68f));
    Marker(root, "Spawn_Right", new Vector2(7.0f, -2.68f));
});
report.AppendLine(t03Path);

// ---------- 配置 + 目录 ----------
if (!Directory.Exists("Assets/GameData/Tutorials")) Directory.CreateDirectory("Assets/GameData/Tutorials");
AssetDatabase.Refresh();

var tutorialCatalog = AssetDatabase.LoadAssetAtPath<LevelCatalog>("Assets/GameData/TutorialCatalog.asset");
var configs = new List<LevelConfig>();

void MakeConfig(string id, string display, string prefabPath)
{
    var assetPath = "Assets/GameData/Tutorials/" + id + ".asset";
    var config = AssetDatabase.LoadAssetAtPath<LevelConfig>(assetPath);
    if (config == null)
    {
        config = ScriptableObject.CreateInstance<LevelConfig>();
        AssetDatabase.CreateAsset(config, assetPath);
    }

    var so = new SerializedObject(config);
    so.FindProperty("levelId").stringValue = id;
    so.FindProperty("displayName").stringValue = display;
    so.FindProperty("enabled").boolValue = true;
    so.FindProperty("levelPrefab").objectReferenceValue = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
    so.FindProperty("windowSize").vector2Value = new Vector2(4f, 3f);
    so.FindProperty("leftWindowOffset").vector2Value = new Vector2(8f, 0f);
    so.FindProperty("rightWindowOffset").vector2Value = new Vector2(-8f, 0f);
    so.ApplyModifiedPropertiesWithoutUndo();

    configs.Add(config);
    report.AppendLine("config " + assetPath);
}

MakeConfig("T001", "教学 1 · 移动与视口", t01Path);
MakeConfig("T002", "教学 2 · 颜料罐与补笔带", t02Path);
MakeConfig("T003", "教学 3 · 颜料碴", t03Path);

tutorialCatalog.SetLevels(configs);
EditorUtility.SetDirty(tutorialCatalog);

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();
report.AppendLine($"TutorialCatalog count={tutorialCatalog.Count}");
return report.ToString();

