    yield return null;
    yield return new WaitForSeconds(3.2f);

    sb.AppendLine($"start level={session.Current?.LevelId}");
    foreach (var col in UnityEngine.Object.FindObjectsOfType<Collider2D>())
        if (col.GetComponent<BeaconSwitch>() != null || col.name.StartsWith("Bridge")) { }

    // T001
    session.LoadIndex(0);
    yield return new WaitForSeconds(3.0f);
    sb.AppendLine($"T001 level={session.Current?.LevelId} goals={UnityEngine.Object.FindObjectsOfType<LevelGoal>().Length}");

    // T002：先看桥状态，再踩开关
    session.LoadIndex(1);
    yield return new WaitForSeconds(3.0f);

    var bridges = UnityEngine.Object.FindObjectsOfType<ToggleBlock>();
    sb.AppendLine($"T002 level={session.Current?.LevelId} bridges={bridges.Length} active0={(bridges.Length > 0 && bridges[0].Active)}");

