    sb.AppendLine($"T002 after switch: active0={(bridges.Length > 0 && bridges[0].Active)} scaleX={(bridges.Length > 0 ? bridges[0].transform.localScale.x : 0):F2}");

    // T003
    session.LoadIndex(2);
    yield return new WaitForSeconds(3.0f);
    int spikes = 0;
    foreach (var h in UnityEngine.Object.FindObjectsOfType<Hazard>()) spikes++;
    sb.AppendLine($"T003 level={session.Current?.LevelId} spikes={spikes} goals={UnityEngine.Object.FindObjectsOfType<LevelGoal>().Length}");

    Debug.Log("[TUTORIAL]\n" + sb);
