using System.Collections.Generic;
using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEngine;

var report = new StringBuilder();
var vision = new Vector2(4f, 3f);
var leftOff = new Vector2(8f, 0f);
var rightOff = new Vector2(-8f, 0f);

LevelConfig Make(string id, string display, string prefabPath, string folder)
{
    var assetPath = folder + "/" + id + ".asset";
    var config = AssetDatabase.LoadAssetAtPath<LevelConfig>(assetPath);
    if (config == null)
    {
        config = ScriptableObject.CreateInstance<LevelConfig>();
        AssetDatabase.CreateAsset(config, assetPath);
    }

    var prefab = AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath);
    config.Configure(id, display, prefab, vision, leftOff, rightOff);
    EditorUtility.SetDirty(config);
    return config;
}

var tutorials = new List<LevelConfig>
{
    Make("T001", "教学 1 · 移动与视口", "Assets/Prefabs/GrayBox/T001.prefab", "Assets/GameData/Tutorials"),
    Make("T002", "教学 2 · 颜料罐与补笔带", "Assets/Prefabs/GrayBox/T002.prefab", "Assets/GameData/Tutorials"),
    Make("T003", "教学 3 · 颜料碴", "Assets/Prefabs/GrayBox/T003.prefab", "Assets/GameData/Tutorials")
};

var tutorialCatalog = AssetDatabase.LoadAssetAtPath<LevelCatalog>("Assets/GameData/TutorialCatalog.asset");
tutorialCatalog.SetLevels(tutorials);
EditorUtility.SetDirty(tutorialCatalog);

var l006 = Make("L006", "关卡 6 · 折痕与落差", "Assets/Prefabs/GrayBox/L006.prefab", "Assets/GameData/Levels");
var l007 = Make("L007", "关卡 7 · 双压板", "Assets/Prefabs/GrayBox/L007.prefab", "Assets/GameData/Levels");

var levelCatalog = AssetDatabase.LoadAssetAtPath<LevelCatalog>("Assets/GameData/LevelCatalog.asset");
var list = new List<LevelConfig>(levelCatalog.Levels);
if (!list.Contains(l006)) list.Add(l006);
if (!list.Contains(l007)) list.Add(l007);
levelCatalog.SetLevels(list);
EditorUtility.SetDirty(levelCatalog);

AssetDatabase.SaveAssets();
AssetDatabase.Refresh();

foreach (var c in tutorials) report.AppendLine($"T: {c.name} id={c.LevelId} prefab={(c.LevelPrefab != null ? c.LevelPrefab.name : "NULL")}");
report.AppendLine($"L006 id={l006.LevelId} prefab={(l006.LevelPrefab != null ? l006.LevelPrefab.name : "NULL")}");
report.AppendLine($"L007 id={l007.LevelId} prefab={(l007.LevelPrefab != null ? l007.LevelPrefab.name : "NULL")}");
return report.ToString();

using System.Collections;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    yield return null;

    PlayerMotor2D left = null, right = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
    {
        if (p.Side == PlayerSide.Left) left = p;
        else right = p;
    }
    var lrb = left.GetComponent<Rigidbody2D>();
    var rrb = right.GetComponent<Rigidbody2D>();

    // ---- L006 ----
    session.LoadIndex(5);
    yield return new WaitForSeconds(3.0f);
    sb.AppendLine($"L006={session.Current?.LevelId}");

    foreach (var t in GameObject.FindObjectsOfType<Transform>())
    {
        if (!t.name.StartsWith("Plat_") && t.name != "Mid_R" && t.name != "High_R") continue;
        var col = t.GetComponent<BoxCollider2D>();
        sb.AppendLine($"  {t.name} top={(col != null ? col.bounds.max.y : 0):F2}");
    }

    lrb.position = new Vector3(-4.0f, -2.55f, 0f);
    left.transform.position = new Vector3(-4.0f, -2.55f, 0f);
    yield return new WaitForSeconds(0.4f);

    VisionWindow win = null;
    foreach (var w in UnityEngine.Object.FindObjectsOfType<VisionWindow>())
        if (w.Side == PlayerSide.Left) win = w;
    var c = win.ResolveCenter();
    sb.AppendLine($"  crease={win.HasCrease} center={c} yRange={c.y - win.Size.y / 2:F2}..{c.y + win.Size.y / 2:F2}");

    // ---- L007 ----
    session.LoadIndex(6);
    yield return new WaitForSeconds(3.0f);
    sb.AppendLine($"L007={session.Current?.LevelId}");

    ToggleBlock bridge = null;
    foreach (var b in UnityEngine.Object.FindObjectsOfType<ToggleBlock>()) bridge = b;
    var gate = UnityEngine.Object.FindObjectOfType<TandemGate>();
    sb.AppendLine($"  bridgeActive={(bridge != null && bridge.Active)} gateOpen={(gate != null && gate.Open)}");

    lrb.position = new Vector3(-6.0f, -2.6f, 0f);
    left.transform.position = new Vector3(-6.0f, -2.6f, 0f);
    yield return new WaitForSeconds(0.35f);
    sb.AppendLine($"  after A: gateOpen={(gate != null && gate.Open)} bridgeActive={(bridge != null && bridge.Active)}");

    rrb.position = new Vector3(4.0f, -2.6f, 0f);
    right.transform.position = new Vector3(4.0f, -2.6f, 0f);
    yield return new WaitForSeconds(0.4f);
    sb.AppendLine($"  after B: gateOpen={(gate != null && gate.Open)} bridgeActive={(bridge != null && bridge.Active)}");

    lrb.position = new Vector3(-7.3f, -2.68f, 0f);
    left.transform.position = new Vector3(-7.3f, -2.68f, 0f);
    yield return new WaitForSeconds(0.5f);
    sb.AppendLine($"  after leaving A: gateOpen={(gate != null && gate.Open)} bridgeActive={(bridge != null && bridge.Active)} (one-shot 应保持)");

    Debug.Log("[NEW_LEVELS]\n" + sb);
}

return Run();

