using System.Collections;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    yield return null;
    yield return new WaitForSeconds(3.2f);

    sb.AppendLine($"start={session.Current?.LevelId}");

    for (int i = 0; i < 3; i++)
    {
        session.LoadIndex(i);
        yield return new WaitForSeconds(2.8f);

        int goals = UnityEngine.Object.FindObjectsOfType<LevelGoal>().Length;
        int spikes = UnityEngine.Object.FindObjectsOfType<Hazard>().Length;
        int bridges = UnityEngine.Object.FindObjectsOfType<ToggleBlock>().Length;
        int switches = UnityEngine.Object.FindObjectsOfType<Switch>().Length;

        sb.AppendLine($"[{i}] {session.Current?.LevelId} goals={goals} spikes={spikes} bridges={bridges} switches={switches}");
    }

    // T002 测开关
    session.LoadIndex(1);
    yield return new WaitForSeconds(2.8f);

    PlayerMotor2D left = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
        if (p.Side == PlayerSide.Left) left = p;

    ToggleBlock bl = null;
    foreach (var b in UnityEngine.Object.FindObjectsOfType<ToggleBlock>())
        if (b.name == "Bridge_Left") bl = b;

    var rb = left.GetComponent<Rigidbody2D>();
    rb.position = new Vector3(-6.4f, -2.6f, 0f);
    left.transform.position = new Vector3(-6.4f, -2.6f, 0f);
    yield return new WaitForSeconds(0.6f);
    sb.AppendLine($"T002 bridgeLeft active={(bl != null && bl.Active)} scaleX={(bl != null ? bl.transform.localScale.x : 0):F2}");

    Debug.Log("[TUTORIAL_NEW]\n" + sb);
}

return Run();

