using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

var report = new StringBuilder();
var tutorial = AssetDatabase.LoadAssetAtPath<LevelCatalog>("Assets/GameData/TutorialCatalog.asset");
if (tutorial == null) return "NO_TUTORIAL";

void Link(Scene scene)
{
    LevelSession session = null;
    foreach (var root in scene.GetRootGameObjects())
    {
        session = root.GetComponentInChildren<LevelSession>(true);
        if (session != null) break;
    }

    if (session == null) { report.AppendLine(scene.name + ": NO_SESSION"); return; }

    var so = new SerializedObject(session);
    so.FindProperty("tutorialCatalog").objectReferenceValue = tutorial;
    so.ApplyModifiedPropertiesWithoutUndo();
    EditorUtility.SetDirty(session);

    EditorSceneManager.MarkSceneDirty(scene);
    EditorSceneManager.SaveScene(scene);
    report.AppendLine(scene.name + ": tutorialCatalog linked");
}

Link(SceneManager.GetActiveScene());

var ysq = EditorSceneManager.OpenScene("Assets/Scenes/YSQ_TestScene.unity", OpenSceneMode.Additive);
Link(ysq);
EditorSceneManager.CloseScene(ysq, true);

return report.ToString();

using System.Text;
using ThreeCup.GrayBox;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

var report = new StringBuilder();
var tutorial = AssetDatabase.LoadAssetAtPath<LevelCatalog>("Assets/GameData/TutorialCatalog.asset");

var lhj = EditorSceneManager.OpenScene("Assets/Scenes/LHJ_TestScene.unity", OpenSceneMode.Additive);

LevelSession session = null;
foreach (var root in lhj.GetRootGameObjects())
{
    session = root.GetComponentInChildren<LevelSession>(true);
    if (session != null) break;
}

if (session == null) report.AppendLine("LHJ: NO_SESSION");
else
{
    var so = new SerializedObject(session);
    so.FindProperty("tutorialCatalog").objectReferenceValue = tutorial;
    so.ApplyModifiedPropertiesWithoutUndo();
    EditorUtility.SetDirty(session);

    EditorSceneManager.MarkSceneDirty(lhj);
    EditorSceneManager.SaveScene(lhj);
    report.AppendLine("LHJ: tutorialCatalog linked");
}

EditorSceneManager.CloseScene(lhj, true);

// 切回 LHJ 作为工作场景
var active = SceneManager.GetActiveScene();
if (active.isDirty) EditorSceneManager.SaveScene(active);
EditorSceneManager.OpenScene("Assets/Scenes/LHJ_TestScene.unity", OpenSceneMode.Single);

report.AppendLine("active=LHJ_TestScene");
return report.ToString();

using System.Collections;
using System.Reflection;
using System.Text;
using ThreeCup.GrayBox;
using UnityEngine;

IEnumerator Run()
{
    var sb = new StringBuilder();
    var session = UnityEngine.Object.FindObjectOfType<LevelSession>();
    yield return null;
    yield return new WaitForSeconds(3.0f);

    var field = typeof(LevelSession).GetField("tutorialCatalog", BindingFlags.NonPublic | BindingFlags.Instance);
    var tutorial = field?.GetValue(session) as LevelCatalog;

    sb.AppendLine($"tutorialCatalog={(tutorial != null ? tutorial.name + " count=" + tutorial.Count : "NULL")}");
    sb.AppendLine($"current(after start)={session.Current?.LevelId}");

    if (tutorial == null) { Debug.Log("[TUTORIAL_ENTRY]\n" + sb); yield break; }

    // 模拟选关加载 T001
    session.Load(tutorial.Get(0));
    yield return new WaitForSeconds(3.0f);
    sb.AppendLine($"load T001 -> current={session.Current?.LevelId} instance={(session.Instance != null ? session.Instance.name : "NULL")}");

    // 接着通关进 T002
    PlayerMotor2D left = null, right = null;
    foreach (var p in UnityEngine.Object.FindObjectsOfType<PlayerMotor2D>())
    {
        if (p.Side == PlayerSide.Left) left = p;
        else right = p;
    }

    foreach (var g in UnityEngine.Object.FindObjectsOfType<LevelGoal>())
    {
        var t = g.Side == PlayerSide.Left ? left : right;
        if (t == null) continue;
        var rb = t.GetComponent<Rigidbody2D>();
        rb.position = g.transform.position;
        t.transform.position = g.transform.position;
    }
    yield return new WaitForSeconds(0.4f);
    foreach (var g in UnityEngine.Object.FindObjectsOfType<LevelGoal>()) g.TryClean();

    yield return new WaitForSeconds(5.2f);
    sb.AppendLine($"after clear -> current={session.Current?.LevelId}");

    Debug.Log("[TUTORIAL_ENTRY]\n" + sb);
}

return Run();
